			m["Env"] = envMap
			dot = m
		}

		// parse template
		tmpl := template.New(src.name)
		tmpl.Option("missingkey=" + final.MissingKey)
		tmpl.Delims(final.LeftDelim, final.RightDelim)
		tmpl.Funcs(funcMap)
		// add templates from -t
		for _, tArg := range final.Templates {
			alias, pathStr := parseTemplateArg(tArg)
			// pathStr could be file or dir
			info, err := os.Stat(pathStr)
			if err != nil {
				// try as file
				b, err2 := os.ReadFile(pathStr)
				if err2 != nil {
					logError(fmt.Sprintf("failed to read template %s: %v", pathStr, err2))
					os.Exit(1)
				}
				// add as named template
				_, err = tmpl.New(alias).Parse(string(b))
				if err != nil {
					logError(fmt.Sprintf("failed to parse template %s: %v", alias, err))
					os.Exit(1)
				}
			} else {
				if info.IsDir() {
					// walk dir
					filepath.Walk(pathStr, func(p string, info os.FileInfo, err error) error {
						if err != nil {
							return nil
						}
						if info.IsDir() {
							return nil
						}
						rel, _ := filepath.Rel(pathStr, p)
						name := filepath.Join(alias, rel)
						if alias == "" {
							// if alias empty, use rel path? Actually original uses file path as template name
							name = p
							// but when alias empty and path is file, use base? Let's simplify
							// If template arg is path to file without alias, name is file path
							name = p
						}
						// read file
						b, err := os.ReadFile(p)
						if err != nil {
							return nil
						}
						tmpl.New(name).Parse(string(b))
						return nil
					})
				} else {
					b, _ := os.ReadFile(pathStr)
					_, err = tmpl.New(alias).Parse(string(b))
					if err != nil {
						logError(fmt.Sprintf("failed to parse template %s: %v", alias, err))
						os.Exit(1)
					}
				}
			}
		}

		parsed, err := tmpl.Parse(src.content)
		if err != nil {
			logError(fmt.Sprintf("renderTemplate: parse template %s: template: %s: %v", src.name, src.name, err))
			os.Exit(1)
		}
		var buf bytes.Buffer
		err = parsed.Execute(&buf, dot)
		if err != nil {
			logError(fmt.Sprintf("renderTemplate: failed to render template %s: template: %s: %v", src.name, src.name, err))
			os.Exit(1)
		}
		output := buf.String()
		// check empty (only whitespace)
		if strings.TrimSpace(output) == "" {
			// do not write output file per docs, but for stdout still nothing?
			outputs = append(outputs, "")
			continue
		}
		outputs = append(outputs, output)

		// handle out files
		if final.ExecPipe {
			// will pipe to postExec
			continue
		}
		if len(final.Outs) > 0 {
			// idx corresponds
			outPath := final.Outs[idx]
			if outPath == "-" {
				fmt.Print(output)
			} else {
				// ensure parent dirs
				dir := filepath.Dir(outPath)
				os.MkdirAll(dir, 0755)
				// chmod handling
				err = os.WriteFile(outPath, []byte(output), 0644)
				if err != nil {
					logError(fmt.Sprintf("failed to write output: %v", err))
					os.Exit(1)
				}
				if final.Chmod != "" {
					mode, err := strconv.ParseUint(final.Chmod, 8, 32)
					if err == nil {
						os.Chmod(outPath, os.FileMode(mode))
					}
				} else if src.isFile {
					// inherit mode from input file
					if info, err := os.Stat(src.filePath); err == nil {
						os.Chmod(outPath, info.Mode())
					}
				}
			}
		} else {
			// no out specified, write to stdout (if not inputDir)
			// For multiple sources, print each? Original prints sequentially? We'll print each
			fmt.Print(output)
		}
	}

	if final.ExecPipe && len(final.PostExec) > 0 {
		// pipe output to postExec
		// If multiple outputs, join?
		combined := strings.Join(outputs, "")
		err := runPostExec(final.PostExec, combined, true)
		if err != nil {
			logError(err.Error())
			os.Exit(1)
		}
	} else if len(final.PostExec) > 0 {
		// need to run postExec after rendering, without pipe?
		// Original says postExec command after --, with output file already written
		err := runPostExec(final.PostExec, "", false)
		if err != nil {
			logError(err.Error())
			os.Exit(1)
		}
	}

	if final.Verbose {
		logDebug("completed rendering", map[string]interface{}{"templatesRendered": len(sources), "errors": 0, "duration": 0})
	}
}

func parseDatasourceArg(s string) (alias string, urlStr string) {
	if idx := strings.Index(s, "="); idx != -1 {
		alias = s[:idx]
		urlStr = s[idx+1:]
	} else {
		// no alias, derive from path
		urlStr = s
		// alias from base without extension? For file path
		// Remove scheme if present?
		u, err := url.Parse(s)
		if err == nil && u.Scheme != "" {
			// use path base
			base := path.Base(u.Path)
			if base == "" || base == "." || base == "/" {
				alias = ""
			} else {
				// strip extension
				ext := filepath.Ext(base)
				alias = strings.TrimSuffix(base, ext)
			}
		} else {
			base := filepath.Base(s)
			ext := filepath.Ext(base)
			alias = strings.TrimSuffix(base, ext)
		}
	}
	return
}

func parseTemplateArg(s string) (alias string, pathStr string) {
	if idx := strings.Index(s, "="); idx != -1 {
		alias = s[:idx]
		pathStr = s[idx+1:]
	} else {
		alias = filepath.Base(s)
		// if alias is actual file, but original uses file path as template name when no alias
		// For path without alias, template name is the path itself
		alias = s
		pathStr = s
	}
	return
}

func dumpConfigForValidation(pf ParsedFlags) string {
	// Build map similar to original dump
	m := make(map[string]interface{})
	// Only include fields that are relevant for error message? Original included many defaults: leftDelim, rightDelim, missingKey, pluginTimeout
	// We'll include a subset
	if pf.InputDir != "" {
		m["inputDir"] = pf.InputDir
	}
	if len(pf.Files) > 0 {
		m["inputFiles"] = pf.Files
	}
	if pf.InSet {
		// shorten if too long? Original truncated in error message with ...? We saw in earlier error: ` + "`" + `in: hi` + "`" + ` and longer in got truncated with "..."? But we can just include raw
		m["in"] = pf.In
	}
	if pf.OutputDir != "" {
		m["outputDir"] = pf.OutputDir
	}
	if len(pf.Outs) > 0 {
		m["outputFiles"] = pf.Outs
	}
	if pf.OutputMap != "" {
		m["outputMap"] = pf.OutputMap
	}
	if pf.Chmod != "" {
		m["chmod"] = pf.Chmod
	}
	m["leftDelim"] = pf.LeftDelim
	m["rightDelim"] = pf.RightDelim
	m["missingKey"] = pf.MissingKey
	m["pluginTimeout"] = "5s"
	if pf.ExecPipe {
		m["execPipe"] = true
	}
	if len(pf.PostExec) > 0 {
		m["postExec"] = pf.PostExec
	}
	// datasources
	if len(pf.Datasources) > 0 {
		dsMap := make(map[string]interface{})
		for _, ds := range pf.Datasources {
			alias, urlStr := parseDatasourceArg(ds)
			dsMap[alias] = map[string]interface{}{
				"header": map[string]interface{}{},
				"url":    urlStr,
			}
		}
		m["datasources"] = dsMap
	}
	b, _ := yaml.Marshal(m)
	return "---\n" + string(b)
}

func getEnvMap() map[string]string {
	env := make(map[string]string)
	for _, kv := range os.Environ() {
		parts := strings.SplitN(kv, "=", 2)
		if len(parts) == 2 {
			env[parts[0]] = parts[1]
		}
	}
	return env
}

func readDatasource(urlStr string) (interface{}, error) {
	// Handle env, file, stdin, merge etc
	// Parse url
	// If urlStr is empty => error
	if urlStr == "" {
		return nil, fmt.Errorf("empty url")
	}
	// Check for mime type override
	typeParam := os.Getenv("GOMPLATE_TYPE_PARAM")
	if typeParam == "" {
		typeParam = "type"
	}
	// Parse as URL
	u, err := url.Parse(urlStr)
	hasScheme := true
	if err != nil || u.Scheme == "" {
		hasScheme = false
	}
	// If no scheme, treat as file path
	if !hasScheme {
		// treat as file path
		return readFileDatasource(urlStr, "")
	}
	scheme := u.Scheme
	// For file scheme
	switch scheme {
	case "file":
		// path may be empty? Use u.Path
		// query for type
		mime := u.Query().Get(typeParam)
		// handle directory if path ends with /
		if strings.HasSuffix(u.Path, "/") {
			// list dir
			entries, err := os.ReadDir(u.Path)
			if err != nil {
				return nil, err
			}
			var names []string
			for _, e := range entries {
				names = append(names, e.Name())
			}
			return names, nil
		}
		return readFileDatasource(u.Path, mime)
	case "env":
		// env var name is in path or opaque
		varName := ""
		if u.Opaque != "" {
			varName = u.Opaque
		} else {
			varName = strings.TrimPrefix(u.Path, "/")
			if varName == "" {
				varName = u.Host
			}
		}
		// sometimes env var name may include host? Let's clean
		varName = strings.Trim(varName, "/")
		val, ok := os.LookupEnv(varName)
		if !ok {
			val = ""
		}
		mime := u.Query().Get(typeParam)
		if mime == "" {
			// check if file extension? No, env datasource raw string unless mime override
			// If mime override says json, parse
			// Else return raw string
			return val, nil
		}
		// parse based on mime
		return parseContent([]byte(val), mime, varName)
	case "stdin":
		// read stdin
		b, err := io.ReadAll(os.Stdin)
		if err != nil {
			return nil, err
		}
		mime := u.Query().Get(typeParam)
		// if mime empty, try to detect from path? path may have extension
		if mime == "" {
			// if path like /foo.json, use extension
			ext := filepath.Ext(u.Path)
			mime = mimeFromExt(ext)
		}
		return parseContent(b, mime, u.Path)
	default:
		// For merge datasource: merge:file://...|file://...
		if strings.HasPrefix(urlStr, "merge:") {
			// after merge: split by |
			rest := strings.TrimPrefix(urlStr, "merge:")
			parts := strings.Split(rest, "|")
			var merged map[string]interface{}
			merged = make(map[string]interface{})
			for _, part := range parts {
				part = strings.TrimSpace(part)
				if part == "" {
					continue
				}
				data, err := readDatasource(part)
				if err != nil {
					continue
				}
				if m, ok := data.(map[string]interface{}); ok {
					for k, v := range m {
						merged[k] = v
					}
				}
			}
			return merged, nil
		}
		// For http/https etc, stub: try to fetch via http? We can attempt but offline may fail
		// For simplicity, return error or empty
		// Also for other schemes, try file fallback if path exists
		if _, err := os.Stat(urlStr); err == nil {
			return readFileDatasource(urlStr, "")
		}
		// Try as file if scheme is like "file" alternative? Already handled
		// Return error
		return nil, fmt.Errorf("unsupported datasource scheme %s", scheme)
	}
}

func mimeFromExt(ext string) string {
	switch strings.ToLower(ext) {
	case ".json":
		return "application/json"
	case ".yaml", ".yml":
		return "application/yaml"
	case ".toml":
		return "application/toml"
	case ".csv":
		return "text/csv"
	case ".env":
		return "application/x-env"
	default:
		return "text/plain"
	}
}

func readFileDatasource(p string, mimeOverride string) (interface{}, error) {
	// p may be relative
	// Check if directory
	info, err := os.Stat(p)
	if err == nil && info.IsDir() {
		entries, err := os.ReadDir(p)
		if err != nil {
			return nil, err
		}
		var names []string
		for _, e := range entries {
			names = append(names, e.Name())
		}
		return names, nil
	}
	b, err := os.ReadFile(p)
	if err != nil {
		return nil, err
	}
	if mimeOverride == "" {
		ext := filepath.Ext(p)
		mimeOverride = mimeFromExt(ext)
	}
	return parseContent(b, mimeOverride, p)
}

func parseContent(b []byte, mime string, name string) (interface{}, error) {
	// trim mime
	mime = strings.ToLower(strings.Split(mime, ";")[0])
	mime = strings.TrimSpace(mime)
	switch mime {
	case "application/json", "application/array+json", "application/json-array":
		var v interface{}
		if err := json.Unmarshal(b, &v); err != nil {
			// if fails, return raw string? Original would error? Let's return raw
			return string(b), nil
		}
		return v, nil
	case "application/yaml", "text/yaml", "application/x-yaml":
		var v interface{}
		if err := yaml.Unmarshal(b, &v); err != nil {
			return string(b), nil
		}
		// yaml.v3 may produce map[interface{}]interface{}, convert to map[string]interface{}
		return convertYamlMap(v), nil
	case "application/toml", "text/toml":
		var v interface{}
		if err := toml.Unmarshal(b, &v); err != nil {
			return string(b), nil
		}
		return v, nil
	case "text/csv":
		r := csv.NewReader(bytes.NewReader(b))
		records, err := r.ReadAll()
		if err != nil {
			return string(b), nil
		}
		return records, nil
	case "application/x-env":
		// parse env file simple
		m := make(map[string]string)
		lines := strings.Split(string(b), "\n")
		for _, line := range lines {
			line = strings.TrimSpace(line)
			if line == "" || strings.HasPrefix(line, "#") {
				continue
			}
			// remove export prefix
			if strings.HasPrefix(line, "export ") {
				line = strings.TrimPrefix(line, "export ")
			}
			if idx := strings.Index(line, "="); idx != -1 {
				k := strings.TrimSpace(line[:idx])
				v := strings.TrimSpace(line[idx+1:])
				// strip quotes
				if len(v) >= 2 && ((v[0] == '"' && v[len(v)-1] == '"') || (v[0] == '\'' && v[len(v)-1] == '\'')) {
					v = v[1 : len(v)-1]
				}
				m[k] = v
			}
		}
		return m, nil
	case "text/plain", "":
		return string(b), nil
	default:
		// try to detect json if starts with { or [
		trim := strings.TrimSpace(string(b))
		if (strings.HasPrefix(trim, "{") && strings.HasSuffix(trim, "}")) || (strings.HasPrefix(trim, "[") && strings.HasSuffix(trim, "]")) {
			var v interface{}
			if err := json.Unmarshal(b, &v); err == nil {
				return v, nil
			}
		}
		return string(b), nil
	}
}

func convertYamlMap(v interface{}) interface{} {
	switch x := v.(type) {
	case map[interface{}]interface{}:
		m := make(map[string]interface{})
		for k, v2 := range x {
			ks := fmt.Sprintf("%v", k)
			m[ks] = convertYamlMap(v2)
		}
		return m
	case map[string]interface{}:
		for k, v2 := range x {
			x[k] = convertYamlMap(v2)
		}
		return x
	case []interface{}:
		for i, v2 := range x {
			x[i] = convertYamlMap(v2)
		}
		return x
	default:
		return v
	}
}

func buildFuncMap(dsMap map[string]string, contextMap map[string]interface{}, rootOverride interface{}, readDS func(string) (interface{}, error), pf ParsedFlags) template.FuncMap {
	fm := template.FuncMap{}

	// helper to read ds by alias
	var dsCache = make(map[string]interface{})
	var dsErrorCache = make(map[string]error)

	getDS := func(alias string) (interface{}, error) {
		if data, ok := dsCache[alias]; ok {
			return data, dsErrorCache[alias]
		}
		urlStr, ok := dsMap[alias]
		if !ok {
			// try to see if alias itself is a URL (dynamic datasource)
			// check if alias contains ://
			if strings.Contains(alias, "://") {
				data, err := readDS(alias)
				dsCache[alias] = data
				dsErrorCache[alias] = err
				return data, err
			}
			return nil, fmt.Errorf("undefined datasource '%s'", alias)
		}
		data, err := readDS(urlStr)
		dsCache[alias] = data
		dsErrorCache[alias] = err
		return data, err
	}

	// datasource functions
	fm["datasource"] = func(args ...string) (interface{}, error) {
		if len(args) < 1 {
			return nil, fmt.Errorf("datasource requires alias")
		}
		alias := args[0]
		subpath := ""
		if len(args) > 1 {
			subpath = args[1]
		}
		data, err := getDS(alias)
		if err != nil {
			return nil, fmt.Errorf("couldn't read datasource '%s' (%s): %w", alias, dsMap[alias], err)
		}
		if subpath != "" {
			// if data is directory listing, subpath is file inside?
			// Try to read file at subpath if ds is directory?
			// For simplicity, if original url is directory, join and read
			origURL := dsMap[alias]
			// check if orig is dir (ends with / or path is dir)
			// attempt to read subpath as file relative to orig dir
			// If origURL is file dir, we need to get its directory
			// Simplify: if data is []string (dir listing), we try to read file at subpath
			// else attempt to lookup key in map?
			// First try map lookup
			if m, ok := data.(map[string]interface{}); ok {
				if v, ok := m[subpath]; ok {
					return v, nil
				}
			}
			// If not found, try to read as file
			// Resolve base dir from orig URL
			basePath := origURL
			// strip file:// prefix if present
			if strings.HasPrefix(basePath, "file://") {
				basePath = strings.TrimPrefix(basePath, "file://")
			}
			// if basePath is file, get its dir
			if info, err := os.Stat(basePath); err == nil && !info.IsDir() {
				basePath = filepath.Dir(basePath)
			}
			// join subpath
			newPath := filepath.Join(basePath, subpath)
			// try read
			if _, err := os.Stat(newPath); err == nil {
				b, err := os.ReadFile(newPath)
				if err == nil {
					// parse based on ext
					mime := mimeFromExt(filepath.Ext(newPath))
					return parseContent(b, mime, newPath)
				}
			}
			// if still not found, return error that includes path
			return nil, fmt.Errorf("couldn't read datasource '%s' (file://%s)", alias, filepath.Join("/tmp", subpath))
		}
		return data, nil
	}
	fm["ds"] = fm["datasource"]
	fm["include"] = func(args ...string) (string, error) {
		if len(args) < 1 {
			return "", fmt.Errorf("include requires alias")
		}
		alias := args[0]
		subpath := ""
		if len(args) > 1 {
			subpath = args[1]
		}
		data, err := getDS(alias)
		if err != nil {
			return "", fmt.Errorf("couldn't read datasource '%s': %w", alias, err)
		}
		// if subpath, similar handling
		if subpath != "" {
			// try to read file
			origURL := dsMap[alias]
			basePath := origURL
			if strings.HasPrefix(basePath, "file://") {
				basePath = strings.TrimPrefix(basePath, "file://")
			}
			if info, err := os.Stat(basePath); err == nil && !info.IsDir() {
				basePath = filepath.Dir(basePath)
			}
			newPath := filepath.Join(basePath, subpath)
			if b, err := os.ReadFile(newPath); err == nil {
				return string(b), nil
			}
		}
		// if data is string, return it, else marshal?
		if s, ok := data.(string); ok {
			return s, nil
		}
		// if it's map or slice, return JSON?
		b, _ := json.Marshal(data)
		return string(b), nil
	}
	fm["datasourceExists"] = func(alias string) bool {
		_, ok := dsMap[alias]
		return ok
	}
	fm["dsExists"] = fm["datasourceExists"]
	fm["datasourceReachable"] = func(alias string) bool {
		_, err := getDS(alias)
		return err == nil
	}
	fm["listDatasources"] = func() []string {
		var keys []string
		for k := range dsMap {
			keys = append(keys, k)
		}
		sort.Strings(keys)
		return keys
	}
	fm["defineDatasource"] = func(alias string, urlStr string) string {
		if _, ok := dsMap[alias]; !ok {
			dsMap[alias] = urlStr
		}
		return ""
	}

	// data namespace
	fm["data.JSON"] = func(in string) (interface{}, error) {
		var v interface{}
		err := json.Unmarshal([]byte(in), &v)
		return v, err
	}
	fm["data.JSONArray"] = func(in string) (interface{}, error) {
		var v []interface{}
		err := json.Unmarshal([]byte(in), &v)
		return v, err
	}
	fm["json"] = fm["data.JSON"]
	fm["jsonArray"] = fm["data.JSONArray"]
	fm["data.YAML"] = func(in string) (interface{}, error) {
		var v interface{}
		err := yaml.Unmarshal([]byte(in), &v)
		return convertYamlMap(v), err
	}
	fm["data.YAMLArray"] = func(in string) (interface{}, error) {
		var v []interface{}
		err := yaml.Unmarshal([]byte(in), &v)
		return convertYamlMap(v), err
	}
	fm["yaml"] = fm["data.YAML"]
	fm["yamlArray"] = fm["data.YAMLArray"]
	fm["data.TOML"] = func(in string) (interface{}, error) {
		var v interface{}
		err := toml.Unmarshal([]byte(in), &v)
		return v, err
	}
	fm["toml"] = fm["data.TOML"]
	fm["data.CSV"] = func(args ...string) ([][]string, error) {
		// args: [delim] input or delim header input? For CSV simple
		var delim string = ","
		var input string
		if len(args) == 1 {
			input = args[0]
		} else if len(args) == 2 {
			delim = args[0]
			input = args[1]
		} else {
			return nil, fmt.Errorf("invalid args")
		}
		r := csv.NewReader(strings.NewReader(input))
		if delim != "" {
			r.Comma = rune(delim[0])
		}
		records, err := r.ReadAll()
		return records, err
	}
	fm["csv"] = fm["data.CSV"]
	fm["data.CSVByRow"] = func(args ...string) ([]map[string]string, error) {
		var delim string = ","
		var input string
		if len(args) == 1 {
			input = args[0]
		} else if len(args) == 2 {
			// could be delim + input
			delim = args[0]
			input = args[1]
		} else if len(args) == 3 {
			delim = args[0]
