		}
		in := args[len(args)-1]
		indexes := args[:len(args)-1]
		current := in
		for _, idx := range indexes {
			switch cur := current.(type) {
			case map[string]interface{}:
				key := fmt.Sprintf("%v", idx)
				if v, ok := cur[key]; ok {
					current = v
				} else {
					return nil, fmt.Errorf("map has no entry for key %s", key)
				}
			case []interface{}:
				i := toInt(idx)
				if i < 0 || i >= len(cur) {
					return nil, fmt.Errorf("index out of range")
