	fm["coll.JSONPath"] = func(expr string, in interface{}) (interface{}, error) {
		// simple dot notation? We'll implement basic $.a.b or $.a[0] ?
		// For simplicity, support $.key or $.key1.key2
		expr = strings.TrimSpace(expr)
		if strings.HasPrefix(expr, "$.") {
			expr = strings.TrimPrefix(expr, "$.")
		} else if expr == "$" {
			return in, nil
		}
		parts := strings.Split(expr, ".")
		current := in
		for _, p := range parts {
			if current == nil {
				return nil, nil
			}
			// handle array index like a[0]
			re := regexp.MustCompile(`^([^\[]+)\[(\d+)\]$`)
			if m := re.FindStringSubmatch(p); m != nil {
				key := m[1]
				idx := toInt(m[2])
				if mp, ok := current.(map[string]interface{}); ok {
					if v, ok := mp[key]; ok {
						current = v
					} else {
						return nil, nil
					}
				}
				if sl, ok := current.([]interface{}); ok {
					if idx >= 0 && idx < len(sl) {
						current = sl[idx]
					} else {
						return nil, nil
					}
				} else if sl2, ok := current.([]string); ok {
					if idx >= 0 && idx < len(sl2) {
						current = sl2[idx]
					}
				}
			} else {
				switch cur := current.(type) {
				case map[string]interface{}:
					if v, ok := cur[p]; ok {
						current = v
					} else {
						return nil, nil
					}
				default:
					return nil, nil
				}
			}
		}
		return current, nil
	}
