func isSlice(v interface{}) bool {
	switch v.(type) {
	case []interface{}, []string, [][]string, []int, []int64:
		return true
	default:
		return false
	}
}

func toSlice(v interface{}) []interface{} {
	switch x := v.(type) {
	case []interface{}:
		return x
	case []string:
		var res []interface{}
		for _, s := range x {
			res = append(res, s)
		}
		return res
	case [][]string:
		var res []interface{}
		for _, r := range x {
			res = append(res, r)
		}
		return res
	default:
		return []interface{}{v}
	}
}

func toInt(v interface{}) int {
	return int(toInt64(v))
}

func toInt64(v interface{}) int64 {
	switch x := v.(type) {
	case int:
		return int64(x)
	case int64:
		return x
	case int32:
		return int64(x)
	case uint:
		return int64(x)
	case uint64:
		return int64(x)
	case float64:
		return int64(x)
	case float32:
		return int64(x)
	case string:
		// try parse int with base 0 to handle hex, octal
		s := strings.TrimSpace(x)
		if s == "" {
			return 0
		}
		// handle NaN, Inf?
		lower := strings.ToLower(s)
		if lower == "nan" || lower == "inf" || lower == "+inf" || lower == "-inf" {
			return 0
		}
		if i, err := strconv.ParseInt(s, 0, 64); err == nil {
			return i
		}
		if f, err := strconv.ParseFloat(s, 64); err == nil {
			return int64(f)
		}
		return 0
	default:
		return 0
	}
}

func toFloat64(v interface{}) float64 {
	switch x := v.(type) {
	case int:
		return float64(x)
	case int64:
		return float64(x)
	case float64:
		return x
	case float32:
		return float64(x)
	case string:
		if f, err := strconv.ParseFloat(x, 64); err == nil {
			return f
		}
		if i, err := strconv.ParseInt(x, 0, 64); err == nil {
			return float64(i)
		}
		return 0
	default:
		return 0
	}
}

func toBool(v interface{}) bool {
	switch x := v.(type) {
	case bool:
		return x
	case string:
		lower := strings.ToLower(strings.TrimSpace(x))
		if lower == "true" || lower == "1" || lower == "yes" || lower == "y" || lower == "t" {
			return true
		}
		if lower == "false" || lower == "0" || lower == "no" || lower == "n" || lower == "f" || lower == "" {
			return false
		}
		// try int
		if i, err := strconv.Atoi(lower); err == nil {
			return i != 0
		}
		return true
	case int:
		return x != 0
	case int64:
		return x != 0
	case float64:
		return x != 0
	case nil:
		return false
	default:
		return true
	}
}

func isFloat(v interface{}) bool {
	switch x := v.(type) {
	case float32, float64:
		return true
	case string:
		_, err := strconv.ParseFloat(x, 64)
		if err == nil {
			// if contains dot or e?
			return strings.Contains(x, ".") || strings.Contains(strings.ToLower(x), "e")
		}
		return false
	default:
		return false
	}
}

func isEmpty(v interface{}) bool {
	if v == nil {
		return true
	}
	switch x := v.(type) {
	case string:
		return x == ""
	case bool:
		return !x
	case int:
		return x == 0
	case int64:
		return x == 0
	case float64:
		return x == 0
	case []interface{}:
		return len(x) == 0
	case []string:
		return len(x) == 0
	case map[string]interface{}:
		return len(x) == 0
	case map[string]string:
		return len(x) == 0
	default:
		return false
	}
}

func getKind(v interface{}) string {
	if v == nil {
		return "invalid"
	}
	switch v.(type) {
	case string:
		return "string"
	case bool:
		return "bool"
	case int, int8, int16, int32, int64:
		return "int"
	case uint, uint8, uint16, uint32, uint64:
		return "uint"
	case float32, float64:
		return "float64"
	case []interface{}, []string, [][]string:
		return "slice"
	case map[string]interface{}, map[string]string:
		return "map"
	default:
		return fmt.Sprintf("%T", v)
	}
}

func compareSemver(a, b string) int {
	// naive compare
	partsA := strings.Split(a, ".")
	partsB := strings.Split(b, ".")
	maxLen := len(partsA)
	if len(partsB) > maxLen {
		maxLen = len(partsB)
	}
	for i := 0; i < maxLen; i++ {
		var av, bv int
		if i < len(partsA) {
			av = toInt(partsA[i])
		}
		if i < len(partsB) {
			bv = toInt(partsB[i])
		}
		if av < bv {
			return -1
		}
		if av > bv {
			return 1
		}
	}
	return 0
}

func processInputDir(pf ParsedFlags, funcMap template.FuncMap, contextMap map[string]interface{}, rootOverride interface{}, dsMap map[string]string, readDS func(string) (interface{}, error)) error {
	inputDir := pf.InputDir
	outputDir := pf.OutputDir
	outputMapStr := pf.OutputMap

	// Walk inputDir
	var files []string
	err := filepath.Walk(inputDir, func(path string, info os.FileInfo, err error) error {
		if err != nil {
			return err
		}
		if info.IsDir() {
			// check .gomplateignore
			// look for .gomplateignore in this dir
			ignorePath := filepath.Join(path, ".gomplateignore")
			if _, err := os.Stat(ignorePath); err == nil {
				// read ignore patterns?
				// For simplicity, we will handle .gomplateignore at root only? But we can store global excludes
			}
			return nil
		}
		files = append(files, path)
		return nil
	})
	if err != nil {
		return err
	}

	// Filter excludes/includes
	// Use pf.Excludes and pf.Includes and also .gomplateignore
	// Read .gomplateignore from inputDir if exists
	var ignorePatterns []string
	if b, err := os.ReadFile(filepath.Join(inputDir, ".gomplateignore")); err == nil {
		lines := strings.Split(string(b), "\n")
		for _, l := range lines {
			l = strings.TrimSpace(l)
			if l != "" && !strings.HasPrefix(l, "#") {
				ignorePatterns = append(ignorePatterns, l)
			}
		}
	}
	// Also check each directory for .gomplateignore? Simplified

	// For each file, check if should exclude
	var filtered []string
	for _, f := range files {
		rel, _ := filepath.Rel(inputDir, f)
		// check include patterns: if includes set, only include matching
		if len(pf.Includes) > 0 {
			matched := false
			for _, pat := range pf.Includes {
				if ok, _ := filepath.Match(pat, filepath.Base(f)); ok {
					matched = true
					break
				}
				if ok, _ := filepath.Match(pat, rel); ok {
					matched = true
					break
				}
			}
			if !matched {
				continue
			}
		}
		// check excludes
		excluded := false
		for _, pat := range pf.Excludes {
			// handle negated with !
			if strings.HasPrefix(pat, "!") {
				negPat := strings.TrimPrefix(pat, "!")
				if ok, _ := filepath.Match(negPat, filepath.Base(f)); ok {
					excluded = false
					continue
				}
				if ok, _ := filepath.Match(negPat, rel); ok {
					excluded = false
					continue
				}
			} else {
				if ok, _ := filepath.Match(pat, filepath.Base(f)); ok {
					excluded = true
				}
				if ok, _ := filepath.Match(pat, rel); ok {
					excluded = true
				}
			}
		}
		for _, pat := range ignorePatterns {
			if ok, _ := filepath.Match(pat, filepath.Base(f)); ok {
				excluded = true
			}
			if ok, _ := filepath.Match(pat, rel); ok {
				excluded = true
			}
		}
		if excluded {
			continue
		}
		filtered = append(filtered, f)
	}

	// For each file, process or copy if exclude-processing
	for _, f := range filtered {
		rel, _ := filepath.Rel(inputDir, f)
		// check exclude-processing
		isExcludeProcessing := false
		for _, pat := range pf.ExcludeProcessing {
			if ok, _ := filepath.Match(pat, filepath.Base(f)); ok {
				isExcludeProcessing = true
				break
			}
			if ok, _ := filepath.Match(pat, rel); ok {
				isExcludeProcessing = true
				break
			}
		}
		var outPath string
		if outputMapStr != "" {
			// Need to render outputMap as template with context .in = rel, .ctx = root? And contextMap?
			// Build dot for outputMap template
			dotMap := make(map[string]interface{})
			for k, v := range contextMap {
				dotMap[k] = v
			}
			dotMap["in"] = rel
			if rootOverride != nil {
				if m, ok := rootOverride.(map[string]interface{}); ok {
					dotMap["ctx"] = m
					for k, v := range m {
						// copy if not conflicting with in, ctx
						if k != "in" && k != "ctx" {
							if _, exists := dotMap[k]; !exists {
								dotMap[k] = v
							}
						}
					}
				} else {
					dotMap["ctx"] = rootOverride
				}
			} else {
				// Env
				dotMap["Env"] = getEnvMap()
			}
			// Also include datasources? For outputMap, all datasources and external nested templates are available
			// We'll use same funcMap

			tmpl := template.New("output-map")
			tmpl.Option("missingkey=zero")
			tmpl.Delims(pf.LeftDelim, pf.RightDelim)
			tmpl.Funcs(funcMap)
			// add templates
			for _, tArg := range pf.Templates {
				alias, pathStr := parseTemplateArg(tArg)
				if b, err := os.ReadFile(pathStr); err == nil {
					tmpl.New(alias).Parse(string(b))
				}
			}
			parsed, err := tmpl.Parse(outputMapStr)
			if err != nil {
				return fmt.Errorf("failed to parse output-map: %v", err)
			}
			var buf bytes.Buffer
			err = parsed.Execute(&buf, dotMap)
			if err != nil {
				return fmt.Errorf("failed to render output-map: %v", err)
			}
			outPath = strings.TrimSpace(buf.String())
		} else {
			outPath = filepath.Join(outputDir, rel)
		}

		if isExcludeProcessing {
			// copy file without parsing
			// ensure dir exists
			os.MkdirAll(filepath.Dir(outPath), 0755)
			b, err := os.ReadFile(f)
			if err != nil {
				return err
			}
			err = os.WriteFile(outPath, b, 0644)
			if err != nil {
				return err
			}
			continue
		}
		// process as template
		b, err := os.ReadFile(f)
		if err != nil {
			return err
		}
		// template dot similar to earlier
		var dot interface{}
		if rootOverride != nil {
			// check if rootOverride is map? If it's map, we still want Env? But earlier root override without Env loses Env
			// So dot = rootOverride
			dot = rootOverride
		} else {
			m := make(map[string]interface{})
			for k, v := range contextMap {
				m[k] = v
			}
			m["Env"] = getEnvMap()
			dot = m
		}
		tmpl := template.New(f)
		tmpl.Option("missingkey=" + pf.MissingKey)
		tmpl.Delims(pf.LeftDelim, pf.RightDelim)
		tmpl.Funcs(funcMap)
		// add templates
		for _, tArg := range pf.Templates {
			alias, pathStr := parseTemplateArg(tArg)
			if b, err := os.ReadFile(pathStr); err == nil {
				tmpl.New(alias).Parse(string(b))
			}
		}
		parsed, err := tmpl.Parse(string(b))
		if err != nil {
			return fmt.Errorf("renderTemplate: failed to render template %s: template: %s: %v", f, f, err)
		}
		var buf bytes.Buffer
		err = parsed.Execute(&buf, dot)
		if err != nil {
			return fmt.Errorf("renderTemplate: failed to render template %s: template: %s: %v", f, f, err)
		}
		output := buf.String()
		if strings.TrimSpace(output) == "" {
			continue
		}
		// write to outPath
		os.MkdirAll(filepath.Dir(outPath), 0755)
		err = os.WriteFile(outPath, []byte(output), 0644)
		if err != nil {
			return err
		}
		if pf.Chmod != "" {
			mode, err := strconv.ParseUint(pf.Chmod, 8, 32)
			if err == nil {
				os.Chmod(outPath, os.FileMode(mode))
			}
		} else {
			// inherit mode
			if info, err := os.Stat(f); err == nil {
				os.Chmod(outPath, info.Mode())
			}
		}
	}
	return nil
}

