					if i >= len(args) { return pf, fmt.Errorf("flag needs an argument: %s", name) }
					val = args[i]
				}
				pf.Templates = append(pf.Templates, val)
			case "-V":
				pf.Verbose = true
			case "-h":
				pf.Help = true
			case "-v":
				pf.Version = true
			default:
				// handle like -f value as -f
				if len(name) == 2 {
					return pf, fmt.Errorf("unknown shorthand flag: %s", name)
				} else {
					// maybe combined like -fOther? Not support
					return pf, fmt.Errorf("unknown shorthand flag: %s", arg)
				}
			}
		} else {
			// positional arg? In gomplate, positional not used except postExec after --, but we treat as error? Original prints error unknown command? We saw "unknown command" for help. For extra args without --, it might error.
			return pf, fmt.Errorf("unknown command %q for \"gomplate\"", arg)
		}
		i++
	}
	return pf, nil
}

func getLogFormat() string {
	if v, ok := os.LookupEnv("GOMPLATE_LOG_FORMAT"); ok {
		return v
	}
	// check if stderr is tty
	if term.IsTerminal(int(os.Stderr.Fd())) {
		return "console"
	}
	return "json"
}

func logError(errMsg string) {
	format := getLogFormat()
	now := time.Now().UTC()
	switch format {
	case "json":
		// time format similar to RFC3339Nano
		m := map[string]string{
			"time":  now.Format(time.RFC3339Nano),
			"level": "ERROR",
			"msg":   "",
			"err":   errMsg,
		}
		b, _ := json.Marshal(m)
		fmt.Fprintln(os.Stderr, string(b))
	case "console":
		// HH:MM:SS
		tstr := now.Format("15:04:05")
		fmt.Fprintf(os.Stderr, "%s ERR  err=%q\n", tstr, errMsg)
	case "logfmt":
		tstr := now.Format(time.RFC3339Nano)
		// need to quote?
		fmt.Fprintf(os.Stderr, "time=%s level=ERROR msg=\"\" err=%q\n", tstr, errMsg)
	case "simple":
		fmt.Fprintf(os.Stderr, "   err=%q\n", errMsg)
	default:
		// json fallback
		m := map[string]string{
			"time":  now.Format(time.RFC3339Nano),
			"level": "ERROR",
			"msg":   "",
			"err":   errMsg,
		}
		b, _ := json.Marshal(m)
		fmt.Fprintln(os.Stderr, string(b))
	}
}

func logDebug(msg string, extra map[string]interface{}) {
	if getLogFormat() == "json" {
		m := map[string]interface{}{
			"time":  time.Now().UTC().Format(time.RFC3339Nano),
			"level": "DEBUG",
			"msg":   msg,
		}
		for k, v := range extra {
			m[k] = v
		}
		b, _ := json.Marshal(m)
		fmt.Fprintln(os.Stderr, string(b))
	} else {
		// simplified
		// for console etc, just print msg
		fmt.Fprintf(os.Stderr, "DEBUG %s\n", msg)
	}
}

