		var start, end, step int64 = 0, 0, 1
		if len(args) >= 3 {
			start = toInt64(args[0])
			end = toInt64(args[1])
			step = toInt64(args[2])
		} else if len(args) == 2 {
			start = toInt64(args[0])
			end = toInt64(args[1])
			step = 1
		}
		// implement seq logic from provided math.go
		if step == 0 {
			return []int64{}
		}
		if end < start && step > 0 {
			step = -step
		}
		if end > start && step < 0 {
			step = -step
		}
		end -= (end - start) % step
		seq := []int64{start}
		last := start
		for last != end {
			last = seq[len(seq)-1] + step
			seq = append(seq, last)
		}
		return seq
	}

