}
func (c CollFuncs) JSONPath(expr string, in interface{}) (interface{}, error) {
	expr=strings.TrimSpace(expr)
	if strings.HasPrefix(expr, "$.") { expr=strings.TrimPrefix(expr, "$.") } else if expr=="$" { return in, nil }
	parts:=strings.Split(expr, ".")
	current:=in
	for _, p:=range parts {
		if current==nil { return nil, nil }
		re:=regexp.MustCompile(`^([^\[]+)\[(\d+)\]$`)
		if m:=re.FindStringSubmatch(p); m!=nil {
			key:=m[1]; idx:=toInt(m[2])
			if mp, ok:=current.(map[string]interface{}); ok {
				if v, ok:=mp[key]; ok { current=v } else { return nil, nil }
			}
			if sl, ok:=current.([]interface{}); ok {
				if idx>=0&&idx<len(sl) { current=sl[idx] } else { return nil, nil }
			}
		} else {
			if mp, ok:=current.(map[string]interface{}); ok {
				if v, ok:=mp[p]; ok { current=v } else { return nil, nil }
			} else { return nil, nil }
		}
	}
	return current, nil
}
func (c CollFuncs) JQ(expr string, in interface{}) (interface{}, error) {
