	ifaces, err:=net.Interfaces()
	if err!=nil { return nil }
	var res []interface{}
	for _, iface:=range ifaces {
		addrs,_:=iface.Addrs()
		for _, addr:=range addrs {
			res=append(res, map[string]interface{}{"name":iface.Name,"address":addr.String(),"type":"ipv4"})
		}
	}
	return res
}
func (s SockaddrFuncs) GetPrivateIP() string {
	addrs,_:=net.InterfaceAddrs()
	for _, addr:=range addrs {
		if ipnet, ok:=addr.(*net.IPNet); ok {
			if ipnet.IP.IsPrivate() && ipnet.IP.To4()!=nil { return ipnet.IP.String() }
		}
	}
	return ""
}
func (s SockaddrFuncs) GetPrivateInterfaces() []interface{} { return s.GetAllInterfaces() }
func (s SockaddrFuncs) GetPublicInterfaces() []interface{} { return []interface{}{} }
func (s SockaddrFuncs) GetDefaultInterfaces() []interface{} { return s.GetAllInterfaces() }
func (s SockaddrFuncs) Include(args ...interface{}) []interface{} {
	if len(args)>=3 { if list, ok:=args[2].([]interface{}); ok { return list } }
	if len(args)>=2 { if list, ok:=args[1].([]interface{}); ok { return list } }
	if len(args)==1 { if list, ok:=args[0].([]interface{}); ok { return list } }
	return []interface{}{}
}
func (s SockaddrFuncs) Exclude(args ...interface{}) []interface{} { return s.Include(args...) }
func (s SockaddrFuncs) Sort(args ...interface{}) []interface{} { return s.Include(args...) }
func (s SockaddrFuncs) Attr(attr string, in interface{}) string {
