func (s SockaddrFuncs) Limit(args ...interface{}) []interface{} { return s.Include(args...) }
func (s SockaddrFuncs) Offset(args ...interface{}) []interface{} { return s.Include(args...) }
func (s SockaddrFuncs) Unique(args ...interface{}) []interface{} { return s.Include(args...) }
