type TestFuncs struct{}
func (t TestFuncs) Assert(args ...interface{}) (string, error) {
	var msg string; var val interface{}
	if len(args)==1 { val=args[0] } else if len(args)>=2 {
		if s, ok:=args[0].(string); ok { msg=s; val=args[1] } else { val=args[0]; if s, ok:=args[1].(string); ok { msg=s } }
	}
	if !toBool(val) {
		if msg=="" { return "", fmt.Errorf("assertion failed") }
		return "", fmt.Errorf("assertion failed: %s", msg)
	}
	return "", nil
}
func (t TestFuncs) Fail(args ...string) (string, error) {
	if len(args)>0 { return "", fmt.Errorf("template generation failed: %s", args[0]) }
	return "", fmt.Errorf("template generation failed")
}
func (t TestFuncs) Ternary(trueVal, falseVal, cond interface{}) interface{} { if toBool(cond) { return trueVal }; return falseVal }
func (t TestFuncs) IsKind(kind string, v interface{}) bool {
	k:=getKind(v)
	if kind=="number" {
		switch k {
		case "int","int8","int16","int32","int64","uint","uint8","uint16","uint32","uint64","float32","float64": return true
		default: return false
		}
	}
	return k==kind
}
func (t TestFuncs) Kind(v interface{}) string { return getKind(v) }
func (t TestFuncs) Required(args ...interface{}) (interface{}, error) {
	var msg string; var val interface{}
	if len(args)==1 { val=args[0] } else if len(args)==2 {
		if s, ok:=args[0].(string); ok { msg=s; val=args[1] } else { val=args[0]; if s, ok:=args[1].(string); ok { msg=s } }
	}
	if isEmpty(val) {
		if msg=="" { msg="value is required" }
		return nil, fmt.Errorf("%s", msg)
	}
	return val, nil
}

type TmplFuncs struct{ tmpl *template.Template }
func (t TmplFuncs) Exec(name string, args ...interface{}) (string, error) { return "", fmt.Errorf("not implemented") }
func (t TmplFuncs) Inline(args ...interface{}) (string, error) {
	var tmplStr string; var ctx interface{}
	if len(args)==1 { tmplStr=fmt.Sprintf("%v", args[0]) } else if len(args)==2 { tmplStr=fmt.Sprintf("%v", args[0]); ctx=args[1] } else if len(args)>=3 { tmplStr=fmt.Sprintf("%v", args[1]); ctx=args[2] }
	tt := template.New("inline")
	parsed, err := tt.Parse(tmplStr)
	if err!=nil { return "", err }
	var buf bytes.Buffer
	dot:=ctx
	if dot==nil { dot=make(map[string]interface{}) }
	err=parsed.Execute(&buf, dot)
	return buf.String(), err
}
