	var delim string=","; var input [][]string
	if len(args)==1 {
		if arr, ok:=args[0].([][]string); ok { input=arr }
	} else if len(args)==2 {
		if d, ok:=args[0].(string); ok { delim=d; if arr, ok:=args[1].([][]string); ok { input=arr } }
	}
	var buf bytes.Buffer
	w:=csv.NewWriter(&buf)
