	needsQuote := false
	if strings.Contains(s, " ") || strings.Contains(s, "{{") || strings.Contains(s, "}}") || strings.Contains(s, "'") || strings.Contains(s, "\\n") || strings.Contains(s, "\\t") {
		needsQuote = true
	}
