	if s=="{{" || s=="}}" {
		return "'{{'" // actually need to handle both
	}
	if needsQuote {
		// Escape single quotes by doubling? For simplicity wrap in single quotes and replace ' with ''
		escaped := strings.ReplaceAll(s, "'", "''")
		return "'" + escaped + "'"
	}
	// If contains ":" or "/" - keep without quotes for urls and paths
	return s
}

func formatYAMLStringArray(arr []string) string {
	var parts []string
	for _, el := range arr {
