# Now we have clean workspace with only original files plus our built executable (which is our implementation). But we need to have source code for our implementation! We deleted main.go, go.mod. We need to recreate them.

# However we still have executable (our implementation) that works. But we need source files to commit.

# Let's write a fresh implementation that is simpler and uses only stdlib, and that we can commit.

# We'll create a new main.go with only stdlib dependencies.

# We'll need to handle yaml config parsing without external lib: implement simple yaml parser for config.

# Let's create a new main.go from scratch, but this time with only stdlib.

cat <<'GO' > main.go
package main

import (
	"bytes"
	"crypto/rand"
	"crypto/sha1"
	"crypto/sha256"
	"crypto/sha512"
	"encoding/base64"
	"encoding/csv"
	"encoding/json"
	"fmt"
	"io"
	"math"
	mathrand "math/rand"
	"net"
	"net/url"
	"os"
	"path"
	"path/filepath"
	"regexp"
	"sort"
	"strconv"
	"strings"
	"text/template"
	"time"
	"os/exec"
)

var version = "0.0.0"

const helpText = `Process text files with Go templates

Usage:
  gomplate [flags]

Flags:
  -d, --datasource datasource        datasource in alias=URL form. Specify multiple times to add multiple sources.
  -H, --datasource-header header     HTTP header field in 'alias=Name: value' form to be provided on HTTP-based data sources. Multiples can be set.
  -c, --context datasource           pre-load a datasource into the context, in alias=URL form. Use the special alias ` + "`" + `.` + "`" + ` to set the root context.
      --plugin strings               plug in an external command as a function in name=path form. Can be specified multiple times
  -f, --file file                    Template file to process. Omit to use standard input, or use --in or --input-dir (default [-])
  -i, --in string                    Template string to process (alternative to --file and --input-dir)
      --input-dir directory          directory which is examined recursively for templates (alternative to --file and --in)
      --exclude strings              glob of files to not parse
      --exclude-processing strings   glob of files to be copied without parsing
      --include strings              glob of files to parse
  -o, --out file                     output file name. Omit to use standard output. (default [-])
  -t, --template strings             Additional template file(s)
      --output-dir directory         directory to store the processed templates. Only used for --input-dir (default ".")
      --output-map string            Template string to map the input file to an output path
      --chmod string                 set the mode for output file(s). Omit to inherit from input file(s)
      --exec-pipe                    pipe the output to the post-run exec command
      --left-delim delimiter         override the default left-delimiter [$GOMPLATE_LEFT_DELIM] (default "{{")
      --right-delim delimiter        override the default right-delimiter [$GOMPLATE_RIGHT_DELIM] (default "}}")
      --missing-key string           Control the behavior during execution if a map is indexed with a key that is not present in the map. error (default) - return an error, zero - fallback to zero value, default/invalid - print <no value> (default "error")
      --experimental                 enable experimental features [$GOMPLATE_EXPERIMENTAL]
  -V, --verbose                      output extra information about what gomplate is doing
      --config string                config file (overridden by commandline flags) (default ".gomplate.yaml")
  -h, --help                         help for gomplate
  -v, --version                      version for gomplate`

type ParsedFlags struct {
	Datasources []string
	DatasourceHeaders []string
	Contexts []string
	Plugins []string
	Files []string
	In string
	InSet bool
	InputDir string
	Excludes []string
	ExcludeProcessing []string
	Includes []string
	Outs []string
	Templates []string
	OutputDir string
	OutputMap string
	Chmod string
	ExecPipe bool
	LeftDelim string
	LeftSet bool
	RightDelim string
	RightSet bool
	MissingKey string
	MissingSet bool
	Experimental bool
	ExperimentalSet bool
	Verbose bool
	Config string
	ConfigSet bool
	Help bool
	Version bool
	PostExec []string
}

func parseArgs(args []string) (ParsedFlags, error) {
	var pf ParsedFlags
	pf.LeftDelim = "{{"
	pf.RightDelim = "}}"
	pf.MissingKey = "error"
	pf.Config = ".gomplate.yaml"
	if v, ok := os.LookupEnv("GOMPLATE_LEFT_DELIM"); ok {
		pf.LeftDelim = v
	}
	if v, ok := os.LookupEnv("GOMPLATE_RIGHT_DELIM"); ok {
		pf.RightDelim = v
	}
	i := 0
	for i < len(args) {
		arg := args[i]
		if arg == "--" {
			if i+1 < len(args) {
				pf.PostExec = args[i+1:]
			}
			break
		}
		if strings.HasPrefix(arg, "--") {
			name := arg
			val := ""
			hasVal := false
			if idx := strings.Index(arg, "="); idx != -1 {
				name = arg[:idx]
				val = arg[idx+1:]
				hasVal = true
			}
			switch name {
			case "--datasource":
				if !hasVal { i++; if i >= len(args) { return pf, fmt.Errorf("flag needs an argument: %s", name) }; val = args[i] }
				pf.Datasources = append(pf.Datasources, val)
			case "--datasource-header":
				if !hasVal { i++; if i >= len(args) { return pf, fmt.Errorf("flag needs an argument: %s", name) }; val = args[i] }
				pf.DatasourceHeaders = append(pf.DatasourceHeaders, val)
			case "--context":
				if !hasVal { i++; if i >= len(args) { return pf, fmt.Errorf("flag needs an argument: %s", name) }; val = args[i] }
				pf.Contexts = append(pf.Contexts, val)
			case "--plugin":
				if !hasVal { i++; if i >= len(args) { return pf, fmt.Errorf("flag needs an argument: %s", name) }; val = args[i] }
				pf.Plugins = append(pf.Plugins, val)
			case "--file":
				if !hasVal { i++; if i >= len(args) { return pf, fmt.Errorf("flag needs an argument: %s", name) }; val = args[i] }
				pf.Files = append(pf.Files, val)
			case "--in":
				if !hasVal { i++; if i >= len(args) { return pf, fmt.Errorf("flag needs an argument: %s", name) }; val = args[i] }
				pf.In = val; pf.InSet = true
			case "--input-dir":
				if !hasVal { i++; if i >= len(args) { return pf, fmt.Errorf("flag needs an argument: %s", name) }; val = args[i] }
				pf.InputDir = val
			case "--exclude":
				if !hasVal { i++; if i >= len(args) { return pf, fmt.Errorf("flag needs an argument: %s", name) }; val = args[i] }
				pf.Excludes = append(pf.Excludes, val)
			case "--exclude-processing":
				if !hasVal { i++; if i >= len(args) { return pf, fmt.Errorf("flag needs an argument: %s", name) }; val = args[i] }
				pf.ExcludeProcessing = append(pf.ExcludeProcessing, val)
			case "--include":
				if !hasVal { i++; if i >= len(args) { return pf, fmt.Errorf("flag needs an argument: %s", name) }; val = args[i] }
				pf.Includes = append(pf.Includes, val)
			case "--out":
				if !hasVal { i++; if i >= len(args) { return pf, fmt.Errorf("flag needs an argument: %s", name) }; val = args[i] }
				pf.Outs = append(pf.Outs, val)
			case "--template":
				if !hasVal { i++; if i >= len(args) { return pf, fmt.Errorf("flag needs an argument: %s", name) }; val = args[i] }
				pf.Templates = append(pf.Templates, val)
			case "--output-dir":
				if !hasVal { i++; if i >= len(args) { return pf, fmt.Errorf("flag needs an argument: %s", name) }; val = args[i] }
				pf.OutputDir = val
			case "--output-map":
				if !hasVal { i++; if i >= len(args) { return pf, fmt.Errorf("flag needs an argument: %s", name) }; val = args[i] }
				pf.OutputMap = val
			case "--chmod":
				if !hasVal { i++; if i >= len(args) { return pf, fmt.Errorf("flag needs an argument: %s", name) }; val = args[i] }
				pf.Chmod = val
			case "--exec-pipe":
				if hasVal { b,_:=strconv.ParseBool(val); pf.ExecPipe=b } else { pf.ExecPipe=true }
			case "--left-delim":
				if !hasVal { i++; if i >= len(args) { return pf, fmt.Errorf("flag needs an argument: %s", name) }; val = args[i] }
				pf.LeftDelim=val; pf.LeftSet=true
			case "--right-delim":
				if !hasVal { i++; if i >= len(args) { return pf, fmt.Errorf("flag needs an argument: %s", name) }; val = args[i] }
				pf.RightDelim=val; pf.RightSet=true
			case "--missing-key":
				if !hasVal { i++; if i >= len(args) { return pf, fmt.Errorf("flag needs an argument: %s", name) }; val = args[i] }
				pf.MissingKey=val; pf.MissingSet=true
			case "--experimental":
				if hasVal { b,_:=strconv.ParseBool(val); pf.Experimental=b } else { pf.Experimental=true }
				pf.ExperimentalSet=true
			case "--verbose":
				if hasVal { b,_:=strconv.ParseBool(val); pf.Verbose=b } else { pf.Verbose=true }
			case "--config":
				if !hasVal { i++; if i >= len(args) { return pf, fmt.Errorf("flag needs an argument: %s", name) }; val = args[i] }
				pf.Config=val; pf.ConfigSet=true
			case "--help":
				pf.Help=true
			case "--version":
				pf.Version=true
			default:
				return pf, fmt.Errorf("unknown flag: %s", name)
			}
		} else if strings.HasPrefix(arg, "-") && len(arg)>1 {
			name:=arg
			val:=""
			hasVal:=false
			if idx:=strings.Index(arg,"="); idx!=-1 {
				name=arg[:idx]; val=arg[idx+1:]; hasVal=true
			}
			switch name {
			case "-d":
				if !hasVal { i++; if i>=len(args){return pf, fmt.Errorf("flag needs an argument: %s", name)}; val=args[i]}
				pf.Datasources=append(pf.Datasources,val)
			case "-H":
				if !hasVal { i++; if i>=len(args){return pf, fmt.Errorf("flag needs an argument: %s", name)}; val=args[i]}
				pf.DatasourceHeaders=append(pf.DatasourceHeaders,val)
			case "-c":
				if !hasVal { i++; if i>=len(args){return pf, fmt.Errorf("flag needs an argument: %s", name)}; val=args[i]}
				pf.Contexts=append(pf.Contexts,val)
			case "-f":
				if !hasVal { i++; if i>=len(args){return pf, fmt.Errorf("flag needs an argument: %s", name)}; val=args[i]}
				pf.Files=append(pf.Files,val)
			case "-i":
				if !hasVal { i++; if i>=len(args){return pf, fmt.Errorf("flag needs an argument: %s", name)}; val=args[i]}
				pf.In=val; pf.InSet=true
			case "-o":
				if !hasVal { i++; if i>=len(args){return pf, fmt.Errorf("flag needs an argument: %s", name)}; val=args[i]}
				pf.Outs=append(pf.Outs,val)
			case "-t":
				if !hasVal { i++; if i>=len(args){return pf, fmt.Errorf("flag needs an argument: %s", name)}; val=args[i]}
				pf.Templates=append(pf.Templates,val)
			case "-V":
				pf.Verbose=true
			case "-h":
				pf.Help=true
			case "-v":
				pf.Version=true
			default:
				return pf, fmt.Errorf("unknown shorthand flag: %s", name)
			}
		} else {
			return pf, fmt.Errorf("unknown command %q for \"gomplate\"", arg)
		}
		i++
	}
	return pf, nil
}

func getLogFormat() string {
	if v, ok := os.LookupEnv("GOMPLATE_LOG_FORMAT"); ok {
		return v
	}
	return "json"
}

func logError(errMsg string) {
	format:=getLogFormat()
	now:=time.Now().UTC()
	switch format {
	case "json":
		m:=map[string]string{"time":now.Format(time.RFC3339Nano),"level":"ERROR","msg":"","err":errMsg}
		b,_:=json.Marshal(m)
		fmt.Fprintln(os.Stderr, string(b))
	case "console":
		tstr:=now.Format("15:04:05")
		fmt.Fprintf(os.Stderr, "%s ERR  err=%q\n", tstr, errMsg)
	case "logfmt":
		tstr:=now.Format(time.RFC3339Nano)
		fmt.Fprintf(os.Stderr, "time=%s level=ERROR msg=\"\" err=%q\n", tstr, errMsg)
	case "simple":
		fmt.Fprintf(os.Stderr, "   err=%q\n", errMsg)
	default:
		m:=map[string]string{"time":now.Format(time.RFC3339Nano),"level":"ERROR","msg":"","err":errMsg}
		b,_:=json.Marshal(m)
		fmt.Fprintln(os.Stderr, string(b))
	}
}

func logDebug(msg string, extra map[string]interface{}) {
	format:=getLogFormat()
	if format=="json" {
		m:=map[string]interface{}{"time":time.Now().UTC().Format(time.RFC3339Nano),"level":"DEBUG","msg":msg}
		for k,v:=range extra { m[k]=v }
		b,_:=json.Marshal(m)
		fmt.Fprintln(os.Stderr, string(b))
	} else {
		fmt.Fprintf(os.Stderr, "DEBUG %s\n", msg)
	}
}

func main() {
	args:=os.Args[1:]
	pf, err := parseArgs(args)
	if err != nil {
		if strings.Contains(err.Error(), "unknown command") {
			fmt.Fprintf(os.Stderr, "Error: %s\n", err.Error())
			usage := `Usage:
  gomplate [flags]

Flags:
  -d, --datasource datasource        datasource in alias=URL form. Specify multiple times to add multiple sources.
  -H, --datasource-header header     HTTP header field in 'alias=Name: value' form to be provided on HTTP-based data sources. Multiples can be set.
  -c, --context datasource           pre-load a datasource into the context, in alias=URL form. Use the special alias ` + "`" + `.` + "`" + ` to set the root context.
      --plugin strings               plug in an external command as a function in name=path form. Can be specified multiple times
  -f, --file file                    Template file to process. Omit to use standard input, or use --in or --input-dir (default [-])
  -i, --in string                    Template string to process (alternative to --file and --input-dir)
      --input-dir directory          directory which is examined recursively for templates (alternative to --file and --in)
      --exclude strings              glob of files to not parse
      --exclude-processing strings   glob of files to be copied without parsing
      --include strings              glob of files to parse
  -o, --out file                     output file name. Omit to use standard output. (default [-])
  -t, --template strings             Additional template file(s)
      --output-dir directory         directory to store the processed templates. Only used for --input-dir (default ".")
      --output-map string            Template string to map the input file to an output path
      --chmod string                 set the mode for output file(s). Omit to inherit from input file(s)
      --exec-pipe                    pipe the output to the post-run exec command
      --left-delim delimiter         override the default left-delimiter [$GOMPLATE_LEFT_DELIM] (default "{{")
      --right-delim delimiter        override the default right-delimiter [$GOMPLATE_RIGHT_DELIM] (default "}}")
      --missing-key string           Control the behavior during execution if a map is indexed with a key that is not present in the map. error (default) - return an error, zero - fallback to zero value, default/invalid - print <no value> (default "error")
      --experimental                 enable experimental features [$GOMPLATE_EXPERIMENTAL]
  -V, --verbose                      output extra information about what gomplate is doing
      --config string                config file (overridden by commandline flags) (default ".gomplate.yaml")
  -h, --help                         help for gomplate
  -v, --version                      version for gomplate
`
			fmt.Println(usage)
			logError(err.Error())
			os.Exit(1)
		} else {
			logError(err.Error())
			os.Exit(1)
		}
	}
	if pf.Help {
		fmt.Println(helpText)
		os.Exit(0)
	}
	if pf.Version {
		fmt.Printf("gomplate version %s\n", version)
		os.Exit(0)
	}

	configPath:=pf.Config
	configSetViaFlag:=pf.ConfigSet
	if !configSetViaFlag {
		if v, ok := os.LookupEnv("GOMPLATE_CONFIG"); ok {
			configPath=v
			configSetViaFlag=true
		}
	}
	var cfgFileContent map[string]interface{}
	if configPath!="" {
		f, err := os.Open(configPath)
		if err!=nil {
			if configSetViaFlag && configPath!=".gomplate.yaml" {
				errMsg:=fmt.Sprintf("config file requested, but couldn't be opened: %v", err)
				fmt.Fprintf(os.Stderr, "Error: %s\n", errMsg)
				fmt.Println(helpText)
				logError(errMsg)
				os.Exit(1)
			} else {
				if _, ok := os.LookupEnv("GOMPLATE_CONFIG"); ok {
					if configPath!="" {
						errMsg:=fmt.Sprintf("config file requested, but couldn't be opened: %v", err)
						fmt.Fprintf(os.Stderr, "Error: %s\n", errMsg)
						fmt.Println(helpText)
						logError(errMsg)
						os.Exit(1)
					}
				}
			}
		} else {
			data, _ := io.ReadAll(f)
			f.Close()
			// Try JSON first, then simple YAML
			var m map[string]interface{}
			if json.Unmarshal(data, &m)==nil {
				cfgFileContent=m
			} else {
				// simple yaml parser
				m2 := parseSimpleYAML(string(data))
				cfgFileContent=m2
			}
		}
	}

	final:=pf
	if !final.LeftSet {
		if v, ok := os.LookupEnv("GOMPLATE_LEFT_DELIM"); ok { final.LeftDelim=v }
	}
	if !final.RightSet {
		if v, ok := os.LookupEnv("GOMPLATE_RIGHT_DELIM"); ok { final.RightDelim=v }
	}
	if !final.ExperimentalSet {
		if v, ok := os.LookupEnv("GOMPLATE_EXPERIMENTAL"); ok {
			b,_:=strconv.ParseBool(v)
			final.Experimental=b
		}
	}
	if cfgFileContent!=nil {
		if len(final.Files)==0 {
			if v, ok := cfgFileContent["inputFiles"]; ok {
				if arr, ok := v.([]interface{}); ok {
					for _, el:=range arr { if s, ok:=el.(string); ok { final.Files=append(final.Files,s) } }
				}
			}
		}
		if len(final.Outs)==0 {
			if v, ok := cfgFileContent["outputFiles"]; ok {
				if arr, ok := v.([]interface{}); ok {
					for _, el:=range arr { if s, ok:=el.(string); ok { final.Outs=append(final.Outs,s) } }
				}
			}
		}
		if final.InputDir=="" {
			if v, ok := cfgFileContent["inputDir"]; ok { if s, ok:=v.(string); ok { final.InputDir=s } }
		}
		if final.OutputDir=="" {
			if v, ok := cfgFileContent["outputDir"]; ok { if s, ok:=v.(string); ok { final.OutputDir=s } }
		}
		if final.OutputMap=="" {
			if v, ok := cfgFileContent["outputMap"]; ok { if s, ok:=v.(string); ok { final.OutputMap=s } }
		}
		if final.In=="" && !final.InSet {
			if v, ok := cfgFileContent["in"]; ok { if s, ok:=v.(string); ok { final.In=s; final.InSet=true } }
		}
		if !final.LeftSet {
			if v, ok := cfgFileContent["leftDelim"]; ok { if s, ok:=v.(string); ok { final.LeftDelim=s } }
		}
		if !final.RightSet {
			if v, ok := cfgFileContent["rightDelim"]; ok { if s, ok:=v.(string); ok { final.RightDelim=s } }
		}
		if !final.MissingSet {
			if v, ok := cfgFileContent["missingKey"]; ok { if s, ok:=v.(string); ok { final.MissingKey=s } }
		}
		if !final.ExperimentalSet {
			if v, ok := cfgFileContent["experimental"]; ok { if b, ok:=v.(bool); ok { final.Experimental=b } }
		}
		if final.Chmod=="" {
			if v, ok := cfgFileContent["chmod"]; ok {
				switch x:=v.(type) {
				case string: final.Chmod=x
				case int: final.Chmod=strconv.Itoa(x)
				}
			}
		}
		if len(final.Datasources)==0 {
			if v, ok := cfgFileContent["datasources"]; ok {
				if m, ok:=v.(map[string]interface{}); ok {
					for alias, cfg := range m {
						if s, ok:=cfg.(string); ok {
							final.Datasources=append(final.Datasources, fmt.Sprintf("%s=%s", alias, s))
						} else if mp, ok:=cfg.(map[string]interface{}); ok {
							if urlVal, ok:=mp["url"]; ok {
								if urlStr, ok:=urlVal.(string); ok {
									final.Datasources=append(final.Datasources, fmt.Sprintf("%s=%s", alias, urlStr))
								}
							}
						}
					}
				}
			}
		}
		if len(final.Contexts)==0 {
			if v, ok := cfgFileContent["context"]; ok {
				if m, ok:=v.(map[string]interface{}); ok {
					for alias, cfg := range m {
						if s, ok:=cfg.(string); ok {
							final.Contexts=append(final.Contexts, fmt.Sprintf("%s=%s", alias, s))
						} else if mp, ok:=cfg.(map[string]interface{}); ok {
							if urlVal, ok:=mp["url"]; ok {
								if urlStr, ok:=urlVal.(string); ok {
									final.Contexts=append(final.Contexts, fmt.Sprintf("%s=%s", alias, urlStr))
								}
							}
						}
					}
				}
			}
		}
		if len(final.Plugins)==0 {
			if v, ok := cfgFileContent["plugins"]; ok {
				if m, ok:=v.(map[string]interface{}); ok {
					for name, cfg := range m {
						if s, ok:=cfg.(string); ok {
							final.Plugins=append(final.Plugins, fmt.Sprintf("%s=%s", name, s))
						} else if mp, ok:=cfg.(map[string]interface{}); ok {
							if cmdVal, ok:=mp["cmd"]; ok {
								if cmdStr, ok:=cmdVal.(string); ok {
									final.Plugins=append(final.Plugins, fmt.Sprintf("%s=%s", name, cmdStr))
								}
							}
						}
					}
				}
			}
		}
		if len(final.Templates)==0 {
			if v, ok := cfgFileContent["templates"]; ok {
				if m, ok:=v.(map[string]interface{}); ok {
					for alias, cfg := range m {
						if s, ok:=cfg.(string); ok {
							final.Templates=append(final.Templates, fmt.Sprintf("%s=%s", alias, s))
						} else if mp, ok:=cfg.(map[string]interface{}); ok {
							if urlVal, ok:=mp["url"]; ok {
								if urlStr, ok:=urlVal.(string); ok {
									pathStr:=urlStr
									if strings.HasPrefix(pathStr, "file://") { pathStr=strings.TrimPrefix(pathStr, "file://") }
									final.Templates=append(final.Templates, fmt.Sprintf("%s=%s", alias, pathStr))
								}
							}
						}
					}
				}
			}
		}
	}

	// Validation
	inputModes:=0
	if final.InSet { inputModes++ }
	if len(final.Files)>0 { inputModes++ }
	if final.InputDir!="" { inputModes++ }
	if inputModes>1 {
		var modes []string
		if final.InSet { modes=append(modes, "'in'") }
		if len(final.Files)>0 { modes=append(modes, "'inputFiles'") }
		if final.InputDir!="" { modes=append(modes, "'inputDir'") }
		errMsg:=fmt.Sprintf("failed to validate config: only one of these options is supported at a time: %s\n---\n", strings.Join(modes, ", "))
		dump:=dumpConfigForValidation(final)
		errMsg=errMsg+dump
		logError(errMsg)
		os.Exit(1)
	}
	if final.OutputDir!="" && final.OutputMap!="" {
		errMsg:=fmt.Sprintf("failed to validate config: only one of these options is supported at a time: 'outputDir', 'outputMap'\n---\n%s", dumpConfigForValidation(final))
		logError(errMsg)
		os.Exit(1)
	}
	if final.OutputDir!="" && final.InputDir=="" {
		errMsg:=fmt.Sprintf("failed to validate config: these options must be set together: 'outputDir', 'inputDir'\n---\n%s", dumpConfigForValidation(final))
		logError(errMsg)
		os.Exit(1)
	}
	if final.OutputMap!="" && final.InputDir=="" {
		errMsg:=fmt.Sprintf("failed to validate config: these options must be set together: 'outputMap', 'inputDir'\n---\n%s", dumpConfigForValidation(final))
		logError(errMsg)
		os.Exit(1)
	}
	if final.ExecPipe && len(final.PostExec)==0 {
		errMsg:=fmt.Sprintf("failed to validate config: execPipe may only be used with a postExec command\n---\n%s", dumpConfigForValidation(final))
		logError(errMsg)
		os.Exit(1)
	}
	inputCount:=1
	if final.InSet { inputCount=1 } else if len(final.Files)>0 { inputCount=len(final.Files) } else if final.InputDir!="" { inputCount=0 }
	if len(final.Outs)>0 {
		if final.InputDir!="" {
			errMsg:=fmt.Sprintf("failed to validate config: only one of these options is supported at a time: 'outputFiles', 'outputDir'\n---\n%s", dumpConfigForValidation(final))
			logError(errMsg)
			os.Exit(1)
		}
		if final.InSet || len(final.Files)>0 {
			if len(final.Outs)!=inputCount {
				errMsg:=fmt.Sprintf("failed to validate config: must provide same number of 'outputFiles' (%d) as 'in' or 'inputFiles' (%d) options\n---\n%s", len(final.Outs), inputCount, dumpConfigForValidation(final))
				logError(errMsg)
				os.Exit(1)
			}
		} else {
			if len(final.Outs)!=1 {
				errMsg:=fmt.Sprintf("failed to validate config: must provide same number of 'outputFiles' (%d) as 'in' or 'inputFiles' (%d) options\n---\n%s", len(final.Outs), inputCount, dumpConfigForValidation(final))
				logError(errMsg)
				os.Exit(1)
			}
		}
	}

	if final.Verbose {
		logDebug("starting gomplate", map[string]interface{}{})
		logDebug(fmt.Sprintf("config is:\n---\n%s\n", dumpConfigForValidation(final)), map[string]interface{}{"version":version,"build":"HEAD"})
	}

	dsMap:=make(map[string]string)
	for _, ds:=range final.Datasources {
		alias, urlStr := parseDatasourceArg(ds)
		dsMap[alias]=urlStr
	}
	contextMap:=make(map[string]interface{})
	var rootOverride interface{}
	rootOverrideSet:=false

	readDS := func(urlStr string) (interface{}, error) { return readDatasource(urlStr) }

	for _, c:=range final.Contexts {
		alias, urlStr := parseDatasourceArg(c)
		data, err := readDS(urlStr)
		if err!=nil {
			logError(fmt.Sprintf("failed to read context %s: %v", alias, err))
			os.Exit(1)
		}
		if alias=="." {
			rootOverride=data
			rootOverrideSet=true
		} else {
			contextMap[alias]=data
		}
	}

	type templateSource struct {
		name string
		content string
		isFile bool
		filePath string
	}
	var sources []templateSource

	if final.InSet {
		sources=append(sources, templateSource{name:"<arg>", content:final.In})
	} else if len(final.Files)>0 {
		for _, f:=range final.Files {
			if f=="-" {
				b,_:=io.ReadAll(os.Stdin)
				sources=append(sources, templateSource{name:"-", content:string(b)})
			} else {
				if _, err := os.Stat(f); err!=nil {
					rel:=f
					if filepath.IsAbs(f) { rel=strings.TrimPrefix(f, "/") }
					logError(fmt.Sprintf("failed to gather templates for rendering: fileToTemplate: stat %q: stat %s: no such file or directory", f, rel))
					os.Exit(1)
				}
				b, err := os.ReadFile(f)
				if err!=nil {
					logError(fmt.Sprintf("failed to gather templates for rendering: fileToTemplate: stat %q: %v", f, err))
					os.Exit(1)
				}
				sources=append(sources, templateSource{name:f, content:string(b), isFile:true, filePath:f})
			}
		}
	} else if final.InputDir!="" {
	} else {
		b,_:=io.ReadAll(os.Stdin)
		sources=append(sources, templateSource{name:"-", content:string(b)})
	}

	funcMap:=buildFuncMap(dsMap, contextMap, readDS, final)

	if final.InputDir!="" {
		err:=processInputDir(final, funcMap, contextMap, rootOverride, dsMap, readDS)
		if err!=nil {
			logError(err.Error())
			os.Exit(1)
		}
		if final.Verbose {
			logDebug("completed rendering", map[string]interface{}{"templatesRendered":0,"errors":0,"duration":0})
		}
		if len(final.PostExec)>0 {
			err:=runPostExec(final.PostExec, "", final.ExecPipe)
			if err!=nil { logError(err.Error()); os.Exit(1) }
		}
		os.Exit(0)
	}

	var outputs []string
	for idx, src:=range sources {
		var dot interface{}
		if rootOverrideSet {
			dot=rootOverride
		} else {
			m:=make(map[string]interface{})
			for k,v:=range contextMap { m[k]=v }
			m["Env"]=getEnvMap()
			dot=m
		}

		tmpl:=template.New(src.name)
		tmpl.Option("missingkey=" + final.MissingKey)
		tmpl.Delims(final.LeftDelim, final.RightDelim)
		tmpl.Funcs(funcMap)
		for _, tArg:=range final.Templates {
			alias, pathStr := parseTemplateArg(tArg)
			info, err := os.Stat(pathStr)
			if err!=nil {
				b, err2 := os.ReadFile(pathStr)
				if err2!=nil {
					logError(fmt.Sprintf("failed to read template %s: %v", pathStr, err2))
					os.Exit(1)
				}
				_, err = tmpl.New(alias).Parse(string(b))
				if err!=nil {
					logError(fmt.Sprintf("failed to parse template %s: %v", alias, err))
					os.Exit(1)
				}
			} else {
				if info.IsDir() {
					filepath.Walk(pathStr, func(p string, info os.FileInfo, err error) error {
						if err!=nil { return nil }
						if info.IsDir() { return nil }
						rel, _ := filepath.Rel(pathStr, p)
						name:=filepath.Join(alias, rel)
						if alias=="" { name=p }
						b, err:=os.ReadFile(p)
						if err!=nil { return nil }
						tmpl.New(name).Parse(string(b))
						return nil
					})
				} else {
					b,_:=os.ReadFile(pathStr)
					tmpl.New(alias).Parse(string(b))
				}
			}
		}

		parsed, err := tmpl.Parse(src.content)
		if err!=nil {
			logError(fmt.Sprintf("renderTemplate: parse template %s: template: %s: %v", src.name, src.name, err))
			os.Exit(1)
		}
		var buf bytes.Buffer
		err=parsed.Execute(&buf, dot)
		if err!=nil {
			logError(fmt.Sprintf("renderTemplate: failed to render template %s: template: %s: %v", src.name, src.name, err))
			os.Exit(1)
		}
		output:=buf.String()
		if strings.TrimSpace(output)=="" {
			outputs=append(outputs, "")
			continue
		}
		outputs=append(outputs, output)

		if final.ExecPipe { continue }

		if len(final.Outs)>0 {
			outPath:=final.Outs[idx]
			if outPath=="-" {
				fmt.Print(output)
			} else {
				dir:=filepath.Dir(outPath)
				os.MkdirAll(dir, 0755)
				err=os.WriteFile(outPath, []byte(output), 0644)
				if err!=nil { logError(fmt.Sprintf("failed to write output: %v", err)); os.Exit(1) }
				if final.Chmod!="" {
					mode,err:=strconv.ParseUint(final.Chmod,8,32)
					if err==nil { os.Chmod(outPath, os.FileMode(mode)) }
				} else if src.isFile {
					if info, err := os.Stat(src.filePath); err==nil { os.Chmod(outPath, info.Mode()) }
				}
			}
		} else {
			fmt.Print(output)
		}
	}

	if final.ExecPipe && len(final.PostExec)>0 {
		combined:=strings.Join(outputs, "")
		err:=runPostExec(final.PostExec, combined, true)
		if err!=nil { logError(err.Error()); os.Exit(1) }
	} else if len(final.PostExec)>0 {
		err:=runPostExec(final.PostExec, "", false)
		if err!=nil { logError(err.Error()); os.Exit(1) }
	}

	if final.Verbose {
		logDebug("completed rendering", map[string]interface{}{"templatesRendered":len(sources),"errors":0,"duration":0})
	}
}

func parseDatasourceArg(s string) (string, string) {
	if idx:=strings.Index(s, "="); idx!=-1 {
		return s[:idx], s[idx+1:]
	}
	u, err := url.Parse(s)
	if err==nil && u.Scheme!="" {
		base:=path.Base(u.Path)
		if base=="" || base=="." || base=="/" { return "", s }
		ext:=filepath.Ext(base)
		return strings.TrimSuffix(base, ext), s
	}
	base:=filepath.Base(s)
	ext:=filepath.Ext(base)
	return strings.TrimSuffix(base, ext), s
}

func parseTemplateArg(s string) (string, string) {
	if idx:=strings.Index(s, "="); idx!=-1 {
		return s[:idx], s[idx+1:]
	}
	return s, s
}

func formatYAMLString(s string) string {
	if s=="-" { return "'-'" }
	if strings.Contains(s, " ") || strings.Contains(s, "{{") || strings.Contains(s, "}}") || strings.Contains(s, "'") {
		escaped:=strings.ReplaceAll(s, "'", "''")
		return "'" + escaped + "'"
	}
	if s=="{{" || s=="}}" {
		if s=="{{" { return "'{{'" } else { return "'}}'" }
	}
	return s
}

func formatYAMLStringArray(arr []string) string {
	var parts []string
	for _, el:=range arr {
		if el=="-" { parts=append(parts, "'-'") } else if strings.Contains(el, " ") || strings.Contains(el, "{{") || strings.Contains(el, "}}") || strings.Contains(el, "'") {
			escaped:=strings.ReplaceAll(el, "'", "''")
			parts=append(parts, "'" + escaped + "'")
		} else { parts=append(parts, el) }
	}
	return "[" + strings.Join(parts, ", ") + "]"
}

func dumpConfigForValidation(pf ParsedFlags) string {
	var sb strings.Builder
	if len(pf.Datasources)>0 {
		sb.WriteString("datasources:\n")
		type dsEntry struct{ alias, url string }
		var entries []dsEntry
		for _, ds:=range pf.Datasources {
			alias, urlStr := parseDatasourceArg(ds)
			entries=append(entries, dsEntry{alias, urlStr})
		}
		sort.Slice(entries, func(i,j int) bool { return entries[i].alias < entries[j].alias })
		for _, e:=range entries {
			sb.WriteString("  " + e.alias + ":\n")
			sb.WriteString("    header: {}\n")
			sb.WriteString("    url: " + formatYAMLString(e.url) + "\n")
		}
	}
	if pf.InSet {
		val:=pf.In
		if strings.Contains(val, "\n") {
			sb.WriteString("in: '" + strings.ReplaceAll(val, "'", "''") + "'\n")
		} else {
			if strings.Contains(val, " ") || strings.Contains(val, "{{") || strings.Contains(val, "}}") {
				sb.WriteString("in: '" + strings.ReplaceAll(val, "'", "''") + "'\n")
			} else {
				sb.WriteString("in: " + val + "\n")
			}
		}
	}
	if pf.InputDir!="" {
		sb.WriteString("inputDir: " + formatYAMLString(pf.InputDir) + "\n")
	}
	if len(pf.Files)>0 {
		sb.WriteString("inputFiles: " + formatYAMLStringArray(pf.Files) + "\n")
	} else if !pf.InSet && pf.InputDir=="" {
		sb.WriteString("inputFiles: ['-']\n")
	}
	if pf.OutputDir!="" {
		sb.WriteString("outputDir: " + formatYAMLString(pf.OutputDir) + "\n")
	}
	if len(pf.Outs)>0 {
		sb.WriteString("outputFiles: " + formatYAMLStringArray(pf.Outs) + "\n")
	} else {
		if pf.OutputDir=="" && pf.OutputMap=="" {
			sb.WriteString("outputFiles: ['-']\n")
		}
	}
	if pf.OutputMap!="" {
		sb.WriteString("outputMap: '" + strings.ReplaceAll(pf.OutputMap, "'", "''") + "'\n")
	}
	sb.WriteString("leftDelim: '" + pf.LeftDelim + "'\n")
	sb.WriteString("rightDelim: '" + pf.RightDelim + "'\n")
	sb.WriteString("missingKey: " + pf.MissingKey + "\n")
	sb.WriteString("pluginTimeout: 5s\n")
	if len(pf.PostExec)>0 {
		sb.WriteString("postExec: " + formatYAMLStringArray(pf.PostExec) + "\n")
	}
	if pf.ExecPipe {
		sb.WriteString("execPipe: true\n")
	}
	if pf.Chmod!="" {
		sb.WriteString("chmod: \"" + pf.Chmod + "\"\n")
	}
	return sb.String()
}

func getEnvMap() map[string]string {
	env:=make(map[string]string)
	for _, kv:=range os.Environ() {
		parts:=strings.SplitN(kv,"=",2)
		if len(parts)==2 { env[parts[0]]=parts[1] }
	}
	return env
}

func readDatasource(urlStr string) (interface{}, error) {
	if urlStr=="" { return nil, fmt.Errorf("empty url") }
	typeParam:=os.Getenv("GOMPLATE_TYPE_PARAM")
	if typeParam=="" { typeParam="type" }
	u, err := url.Parse(urlStr)
	hasScheme:=true
	if err!=nil || u.Scheme=="" { hasScheme=false }
	if !hasScheme {
		return readFileDatasource(urlStr, "")
	}
	scheme:=u.Scheme
	switch scheme {
	case "file":
		mime:=u.Query().Get(typeParam)
		if strings.HasSuffix(u.Path, "/") {
			entries, err := os.ReadDir(u.Path)
			if err!=nil { return nil, err }
			var names []string
			for _, e:=range entries { names=append(names, e.Name()) }
			return names, nil
		}
		return readFileDatasource(u.Path, mime)
	case "env":
		varName:=""
		if u.Opaque!="" { varName=u.Opaque } else {
			varName=strings.TrimPrefix(u.Path, "/")
			if varName=="" { varName=u.Host }
		}
		varName=strings.Trim(varName, "/")
		val, _ := os.LookupEnv(varName)
		mime:=u.Query().Get(typeParam)
		if mime=="" { return val, nil }
		return parseContent([]byte(val), mime, varName)
	case "stdin":
		b, err := io.ReadAll(os.Stdin)
		if err!=nil { return nil, err }
		mime:=u.Query().Get(typeParam)
		if mime=="" {
			ext:=filepath.Ext(u.Path)
			mime=mimeFromExt(ext)
		}
		return parseContent(b, mime, u.Path)
	default:
		if strings.HasPrefix(urlStr, "merge:") {
			rest:=strings.TrimPrefix(urlStr, "merge:")
			parts:=strings.Split(rest, "|")
			merged:=make(map[string]interface{})
			for _, part:=range parts {
				part=strings.TrimSpace(part)
				if part=="" { continue }
				data, err:=readDatasource(part)
				if err!=nil { continue }
				if m, ok:=data.(map[string]interface{}); ok {
					for k,v:=range m { merged[k]=v }
				}
			}
			return merged, nil
		}
		if _, err := os.Stat(urlStr); err==nil {
			return readFileDatasource(urlStr, "")
		}
		return nil, fmt.Errorf("unsupported datasource scheme %s", scheme)
	}
}

func mimeFromExt(ext string) string {
	switch strings.ToLower(ext) {
	case ".json": return "application/json"
	case ".yaml",".yml": return "application/yaml"
	case ".toml": return "application/toml"
	case ".csv": return "text/csv"
	case ".env": return "application/x-env"
	default: return "text/plain"
	}
}

func readFileDatasource(p string, mimeOverride string) (interface{}, error) {
	info, err := os.Stat(p)
	if err==nil && info.IsDir() {
		entries, err := os.ReadDir(p)
		if err!=nil { return nil, err }
		var names []string
		for _, e:=range entries { names=append(names, e.Name()) }
		return names, nil
	}
	b, err := os.ReadFile(p)
	if err!=nil { return nil, err }
	if mimeOverride=="" {
		ext:=filepath.Ext(p)
		mimeOverride=mimeFromExt(ext)
	}
	return parseContent(b, mimeOverride, p)
}

func parseContent(b []byte, mime string, name string) (interface{}, error) {
	mime=strings.ToLower(strings.Split(mime, ";")[0])
	mime=strings.TrimSpace(mime)
	switch mime {
	case "application/json", "application/array+json":
		var v interface{}
		if err:=json.Unmarshal(b,&v); err!=nil { return string(b), nil }
		return v, nil
	case "application/yaml", "text/yaml", "application/x-yaml":
		// try json first (yaml is superset, but for our simple parser try json)
		// Then try simple yaml
		var v interface{}
		if err:=json.Unmarshal(b,&v); err==nil { return v, nil }
		m:=parseSimpleYAML(string(b))
		if len(m)>0 { return m, nil }
		return string(b), nil
	case "application/toml", "text/toml":
		// simple toml parser: key = value
		m:=parseSimpleTOML(string(b))
		if len(m)>0 { return m, nil }
		return string(b), nil
	case "text/csv":
		r:=csv.NewReader(bytes.NewReader(b))
		records, err := r.ReadAll()
		if err!=nil { return string(b), nil }
		return records, nil
	case "application/x-env":
		m:=make(map[string]string)
		lines:=strings.Split(string(b), "\n")
		for _, line:=range lines {
			line=strings.TrimSpace(line)
			if line=="" || strings.HasPrefix(line,"#") { continue }
			if strings.HasPrefix(line,"export ") { line=strings.TrimPrefix(line,"export ") }
			if idx:=strings.Index(line,"="); idx!=-1 {
				k:=strings.TrimSpace(line[:idx])
				v:=strings.TrimSpace(line[idx+1:])
				if len(v)>=2 && ((v[0]=='"' && v[len(v)-1]=='"') || (v[0]=='\'' && v[len(v)-1]=='\'')) {
					v=v[1:len(v)-1]
				}
				m[k]=v
			}
		}
		return m, nil
	case "text/plain","":
		return string(b), nil
	default:
		trim:=strings.TrimSpace(string(b))
		if (strings.HasPrefix(trim,"{") && strings.HasSuffix(trim,"}")) || (strings.HasPrefix(trim,"[") && strings.HasSuffix(trim,"]")) {
			var v interface{}
			if err:=json.Unmarshal(b,&v); err==nil { return v, nil }
		}
		return string(b), nil
	}
}

func parseSimpleYAML(s string) map[string]interface{} {
	m:=make(map[string]interface{})
	lines:=strings.Split(s, "\n")
	for _, line:=range lines {
		line=strings.TrimSpace(line)
		if line=="" || strings.HasPrefix(line,"#") { continue }
		if idx:=strings.Index(line,":"); idx!=-1 {
			k:=strings.TrimSpace(line[:idx])
			v:=strings.TrimSpace(line[idx+1:])
			// remove quotes
			v=strings.Trim(v, "\"'")
			// try int
			if i, err:=strconv.Atoi(v); err==nil {
				m[k]=i
			} else {
				m[k]=v
			}
		}
	}
	return m
}

func parseSimpleTOML(s string) map[string]interface{} {
	m:=make(map[string]interface{})
	lines:=strings.Split(s, "\n")
	for _, line:=range lines {
		line=strings.TrimSpace(line)
		if line=="" || strings.HasPrefix(line,"#") || strings.HasPrefix(line,"[") { continue }
		if idx:=strings.Index(line,"="); idx!=-1 {
			k:=strings.TrimSpace(line[:idx])
			v:=strings.TrimSpace(line[idx+1:])
			v=strings.Trim(v, "\"'")
			if i, err:=strconv.Atoi(v); err==nil { m[k]=i } else { m[k]=v }
		}
	}
	return m
}

// Namespace structs and helpers

type StringFuncs struct{}
func (s StringFuncs) ToUpper(str string) string { return strings.ToUpper(str) }
func (s StringFuncs) ToLower(str string) string { return strings.ToLower(str) }
func (s StringFuncs) Contains(substr, input string) bool { return strings.Contains(input, substr) }
func (s StringFuncs) HasPrefix(prefix, input string) bool { return strings.HasPrefix(input, prefix) }
func (s StringFuncs) HasSuffix(suffix, input string) bool { return strings.HasSuffix(input, suffix) }
func (s StringFuncs) TrimSpace(input string) string { return strings.TrimSpace(input) }
func (s StringFuncs) Trim(cutset, input string) string { return strings.Trim(input, cutset) }
func (s StringFuncs) ReplaceAll(old, new, input string) string { return strings.ReplaceAll(input, old, new) }
func (s StringFuncs) Split(sep, input string) []string { return strings.Split(input, sep) }
func (s StringFuncs) SplitN(sep string, n int, input string) []string { return strings.SplitN(input, sep, n) }
func (s StringFuncs) Repeat(count int, input string) string { return strings.Repeat(input, count) }
func (s StringFuncs) Quote(input string) string { return strconv.Quote(input) }
func (s StringFuncs) Squote(input string) string { return "'" + strings.ReplaceAll(input, "'", "\\'") + "'" }
func (s StringFuncs) Title(input string) string { return strings.Title(input) }
func (s StringFuncs) Slug(input string) string {
	low:=strings.ToLower(input)
	re:=regexp.MustCompile(`[^a-z0-9]+`)
	low=re.ReplaceAllString(low, "-")
	return strings.Trim(low, "-")
}
func (s StringFuncs) ShellQuote(input string) string { return "'" + strings.ReplaceAll(input, "'", "'\"'\"'") + "'" }
func (s StringFuncs) Abbrev(args ...interface{}) string {
	var offset int=0; var width int; var input string
	if len(args)==2 { width=toInt(args[0]); input=fmt.Sprintf("%v", args[1]) } else if len(args)==3 { offset=toInt(args[0]); width=toInt(args[1]); input=fmt.Sprintf("%v", args[2]) }
	if len(input)<=width { return input }
	if offset<4 { return input[:width-3]+"..." }
	end:=offset+width-6
	if end>len(input) { end=len(input) }
	return "..." + input[offset:end] + "..."
}
func (s StringFuncs) Trunc(args ...interface{}) string {
	var offset, width int; var input string
	if len(args)==2 { width=toInt(args[0]); input=fmt.Sprintf("%v", args[1]) } else if len(args)==3 { offset=toInt(args[0]); width=toInt(args[1]); input=fmt.Sprintf("%v", args[2]) }
	if offset>=len(input) { return "" }
	end:=offset+width
	if end>len(input) { end=len(input) }
	return input[offset:end]
}
func (s StringFuncs) Indent(spaces int, input string) string {
	pad:=strings.Repeat(" ", spaces)
	lines:=strings.Split(input, "\n")
	for i,l:=range lines { lines[i]=pad+l }
	return strings.Join(lines, "\n")
}
func (s StringFuncs) WordWrap(width int, input string) string {
	words:=strings.Fields(input)
	var outLines []string
	var line string
	for _, w:=range words {
		if len(line)+len(w)+1>width {
			outLines=append(outLines, line)
			line=w
		} else {
			if line=="" { line=w } else { line+=" "+w }
		}
	}
	if line!="" { outLines=append(outLines, line) }
	return strings.Join(outLines, "\n")
}
func (s StringFuncs) RuneCount(input string) int { return len([]rune(input)) }
func (s StringFuncs) SkipLines(n int, input string) string {
	lines:=strings.Split(input, "\n")
	if n>=len(lines) { return "" }
	return strings.Join(lines[n:], "\n")
}
func (s StringFuncs) CamelCase(input string) string {
	parts:=regexp.MustCompile(`[_\-\s]+`).Split(input,-1)
	for i,p:=range parts { if len(p)>0 { parts[i]=strings.Title(strings.ToLower(p)) } }
	res:=strings.Join(parts,"")
	if len(res)>0 { res=strings.ToLower(res[:1])+res[1:] }
	return res
}
func (s StringFuncs) SnakeCase(input string) string {
	re:=regexp.MustCompile(`([a-z0-9])([A-Z])`)
	input=re.ReplaceAllString(input, "${1}_${2}")
	re2:=regexp.MustCompile(`[\s-]+`)
	input=re2.ReplaceAllString(input, "_")
	return strings.ToLower(input)
}
func (s StringFuncs) KebabCase(input string) string {
	re:=regexp.MustCompile(`([a-z0-9])([A-Z])`)
	input=re.ReplaceAllString(input, "${1}-${2}")
	re2:=regexp.MustCompile(`[_\s]+`)
	input=re2.ReplaceAllString(input, "-")
	return strings.ToLower(input)
}

type MathFuncs struct{}
func (m MathFuncs) Add(args ...interface{}) interface{} {
	hasFloat:=false
	for _, a:=range args { if isFloat(a){hasFloat=true;break} }
	if hasFloat { var sum float64; for _,a:=range args{ sum+=toFloat64(a)}; return sum }
	var sum int64; for _,a:=range args{ sum+=toInt64(a)}; return sum
}
func (m MathFuncs) Mul(args ...interface{}) interface{} {
	hasFloat:=false
	for _, a:=range args { if isFloat(a){hasFloat=true;break} }
	if hasFloat { prod:=1.0; for _,a:=range args{ prod*=toFloat64(a)}; return prod }
	var prod int64=1; for _,a:=range args{ prod*=toInt64(a)}; return prod
}
func (m MathFuncs) Sub(a,b interface{}) interface{} {
	if isFloat(a)||isFloat(b){ return toFloat64(a)-toFloat64(b)}
	return toInt64(a)-toInt64(b)
}
func (m MathFuncs) Div(a,b interface{}) float64 { return toFloat64(a)/toFloat64(b) }
func (m MathFuncs) Pow(a,b interface{}) float64 { return math.Pow(toFloat64(a), toFloat64(b)) }
func (m MathFuncs) Rem(a,b interface{}) interface{} {
	ai:=toInt64(a); bi:=toInt64(b); if bi==0 {return 0}; return ai%bi
}
func (m MathFuncs) Abs(v interface{}) interface{} {
	if isFloat(v){ return math.Abs(toFloat64(v))}
	i:=toInt64(v); if i<0 {return -i}; return i
}
func (m MathFuncs) Ceil(v interface{}) float64 { return math.Ceil(toFloat64(v)) }
func (m MathFuncs) Floor(v interface{}) float64 { return math.Floor(toFloat64(v)) }
func (m MathFuncs) Round(v interface{}) float64 { return math.Round(toFloat64(v)) }
func (m MathFuncs) Max(args ...interface{}) interface{} {
	if len(args)==0 {return nil}
	hasFloat:=false; for _,a:=range args{ if isFloat(a){hasFloat=true}}
	if hasFloat {
		max:=toFloat64(args[0]); for _,a:=range args[1:]{ f:=toFloat64(a); if f>max{max=f}}; return max
	}
	max:=toInt64(args[0]); for _,a:=range args[1:]{ i:=toInt64(a); if i>max{max=i}}; return max
}
func (m MathFuncs) Min(args ...interface{}) interface{} {
	if len(args)==0 {return nil}
	hasFloat:=false; for _,a:=range args{ if isFloat(a){hasFloat=true}}
	if hasFloat {
		min:=toFloat64(args[0]); for _,a:=range args[1:]{ f:=toFloat64(a); if f<min{min=f}}; return min
	}
	min:=toInt64(args[0]); for _,a:=range args[1:]{ i:=toInt64(a); if i<min{min=i}}; return min
}
func (m MathFuncs) IsFloat(v interface{}) bool {
	switch x:=v.(type) {
	case float32,float64: return true
	case string:
		_, err:=strconv.ParseFloat(x,64)
		if err!=nil {return false}
		lower:=strings.ToLower(x)
		if lower=="nan"||lower=="inf"||lower=="+inf"||lower=="-inf" {return true}
		return strings.Contains(x,".") || strings.Contains(strings.ToLower(x),"e")
	default: return false
	}
}
func (m MathFuncs) IsInt(v interface{}) bool {
	switch x:=v.(type) {
	case int,int8,int16,int32,int64,uint,uint8,uint16,uint32,uint64: return true
	case string:
		_, err:=strconv.ParseInt(x,0,64)
		return err==nil
	default: return false
	}
}
func (m MathFuncs) IsNum(v interface{}) bool {
	switch x:=v.(type) {
	case int,int8,int16,int32,int64,uint,uint8,uint16,uint32,uint64,float32,float64: return true
	case string:
		if _, err:=strconv.ParseInt(x,0,64); err==nil {return true}
		if _, err:=strconv.ParseFloat(x,64); err==nil {return true}
		lower:=strings.ToLower(x)
		if lower=="nan"||lower=="inf"||lower=="+inf"||lower=="-inf" {return true}
		return false
	default: return false
	}
}
func (m MathFuncs) Seq(args ...interface{}) []int64 {
	var start,end,step int64=0,0,1
	if len(args)>=3 { start=toInt64(args[0]); end=toInt64(args[1]); step=toInt64(args[2]) } else if len(args)==2 { start=toInt64(args[0]); end=toInt64(args[1]); step=1 }
	if step==0 {return []int64{}}
	if end<start && step>0 { step=-step }
	if end>start && step<0 { step=-step }
	end-=(end-start)%step
	seq:=[]int64{start}
	last:=start
	for last!=end {
		last=seq[len(seq)-1]+step
		seq=append(seq, last)
	}
	return seq
}

type Base64Funcs struct{}
func (b Base64Funcs) Encode(in interface{}) string {
	var buf []byte
	switch v:=in.(type) {
	case string: buf=[]byte(v)
	case []byte: buf=v
	default: buf=[]byte(fmt.Sprintf("%v", v))
	}
	return base64.StdEncoding.EncodeToString(buf)
}
func (b Base64Funcs) Decode(in string) (string, error) {
	by, err:=base64.StdEncoding.DecodeString(in)
	if err!=nil {
		by, err=base64.URLEncoding.DecodeString(in)
		if err!=nil {
			by, err=base64.RawStdEncoding.DecodeString(in)
			if err!=nil { by, err=base64.RawURLEncoding.DecodeString(in) }
		}
	}
	return string(by), err
}
func (b Base64Funcs) DecodeBytes(in string) ([]byte, error) {
	by, err:=base64.StdEncoding.DecodeString(in)
	if err!=nil { by, err=base64.URLEncoding.DecodeString(in) }
	return by, err
}

