		return false
	case map[string]string: _, ok:=v[key]; return ok
	default: return false
	}
}
func (c CollFuncs) Keys(args ...interface{}) []string {
	var keys []string
	for _, arg:=range args {
		switch m:=arg.(type) {
		case map[string]interface{}: for k:=range m { keys=append(keys,k) }
		case map[string]string: for k:=range m { keys=append(keys,k) }
		}
	}
	sort.Strings(keys)
	return keys
}
func (c CollFuncs) Values(args ...interface{}) []interface{} {
	var values []interface{}
	for _, arg:=range args {
		switch m:=arg.(type) {
		case map[string]interface{}:
			var ks []string; for k:=range m { ks=append(ks,k) }; sort.Strings(ks); for _, k:=range ks { values=append(values, m[k]) }
		case map[string]string:
			var ks []string; for k:=range m { ks=append(ks,k) }; sort.Strings(ks); for _, k:=range ks { values=append(values, m[k]) }
		}
	}
	return values
}
func (c CollFuncs) Append(args ...interface{}) []interface{} {
	if len(args)<2 { return nil }
	if len(args)==2 {
		if isSlice(args[1]) && !isSlice(args[0]) {
			list:=toSlice(args[1]); return append(list, args[0])
		}
		if isSlice(args[0]) && !isSlice(args[1]) {
			list:=toSlice(args[0]); return append(list, args[1])
		}
	}
	v:=args[0]
	list:=toSlice(args[len(args)-1])
	return append(list, v)
}
func (c CollFuncs) Prepend(args ...interface{}) []interface{} {
	if len(args)<2 { return nil }
	v:=args[0]
	if isSlice(args[1]) { list:=toSlice(args[1]); return append([]interface{}{v}, list...) }
	if isSlice(args[0]) { list:=toSlice(args[0]); return append([]interface{}{v}, list...) }
	return []interface{}{v}
}
func (c CollFuncs) Uniq(list interface{}) []interface{} {
	slice:=toSlice(list); seen:=make(map[string]bool); var res []interface{}
	for _, el:=range slice { key:=fmt.Sprintf("%v", el); if !seen[key] { seen[key]=true; res=append(res, el) } }
	return res
}
func (c CollFuncs) Reverse(list interface{}) []interface{} {
	slice:=toSlice(list)
	for i,j:=0,len(slice)-1; i<j; i,j=i+1,j-1 { slice[i],slice[j]=slice[j],slice[i] }
	return slice
}
func (c CollFuncs) Sort(list interface{}) []interface{} {
	slice:=toSlice(list)
	sort.Slice(slice, func(i,j int) bool { return fmt.Sprintf("%v", slice[i]) < fmt.Sprintf("%v", slice[j]) })
	return slice
}
func (c CollFuncs) Merge(maps ...map[string]interface{}) map[string]interface{} {
	res:=make(map[string]interface{})
	for _, m := range maps { for k,v:=range m { res[k]=v } }
	return res
}
func (c CollFuncs) Pick(args ...interface{}) map[string]interface{} {
	var in map[string]interface{}
	var keys []string
	if len(args)==0 { return nil }
	if m, ok := args[len(args)-1].(map[string]interface{}); ok {
		in=m; for _, k:=range args[:len(args)-1] { keys=append(keys, fmt.Sprintf("%v", k)) }
	}
	res:=make(map[string]interface{})
	for _, k:=range keys { if v, ok:=in[k]; ok { res[k]=v } }
	return res
}
func (c CollFuncs) Omit(args ...interface{}) map[string]interface{} {
	var in map[string]interface{}
	var keys []string
	if len(args)==0 { return nil }
	if m, ok := args[len(args)-1].(map[string]interface{}); ok {
		in=m; for _, k:=range args[:len(args)-1] { keys=append(keys, fmt.Sprintf("%v", k)) }
	}
	res:=make(map[string]interface{})
	for k,v:=range in { res[k]=v }
	for _, k:=range keys { delete(res, k) }
	return res
}
func (c CollFuncs) Set(args ...interface{}) map[string]interface{} {
	var in map[string]interface{}
	var key string
	var val interface{}
	if len(args)==3 {
		if m, ok := args[len(args)-1].(map[string]interface{}); ok {
			in=m; key=fmt.Sprintf("%v", args[0]); val=args[1]
		}
	}
	if in==nil {
		if m, ok := args[0].(map[string]interface{}); ok {
			in=m
			if len(args)>1 { key=fmt.Sprintf("%v", args[1]) }
			if len(args)>2 { val=args[2] }
		}
	}
	res:=make(map[string]interface{})
	for k,v:=range in { res[k]=v }
	res[key]=val
	return res
}
func (c CollFuncs) Unset(args ...interface{}) map[string]interface{} {
	var in map[string]interface{}
	var key string
	if len(args)==2 {
		if m, ok := args[1].(map[string]interface{}); ok {
			in=m; key=fmt.Sprintf("%v", args[0])
		} else if m, ok := args[0].(map[string]interface{}); ok {
			in=m; key=fmt.Sprintf("%v", args[1])
		}
	}
	res:=make(map[string]interface{})
	for k,v:=range in { res[k]=v }
	delete(res, key)
	return res
}
func (c CollFuncs) Flatten(args ...interface{}) []interface{} {
	var depth int=-1
	var list interface{}
	if len(args)==1 { list=args[0] } else if len(args)==2 { depth=toInt(args[0]); list=args[1] }
	flat:=[]interface{}{}
	var flatten func(interface{}, int)
	flatten = func(v interface{}, d int) {
		if d==0 { flat=append(flat, v); return }
		if isSlice(v) {
			for _, el:=range toSlice(v) { flatten(el, d-1) }
		} else { flat=append(flat, v) }
	}
	flatten(list, depth)
	return flat
}
func (c CollFuncs) Index(args ...interface{}) (interface{}, error) {
	if len(args)<2 { return nil, fmt.Errorf("not enough args") }
	in:=args[len(args)-1]
	indexes:=args[:len(args)-1]
	current:=in
	for _, idx := range indexes {
		switch cur:=current.(type) {
		case map[string]interface{}:
			key:=fmt.Sprintf("%v", idx)
			if v, ok:=cur[key]; ok { current=v } else { return nil, fmt.Errorf("map has no entry for key %s", key) }
		case []interface{}:
			i:=toInt(idx)
			if i<0||i>=len(cur) { return nil, fmt.Errorf("index out of range") }
			current=cur[i]
		default: return nil, fmt.Errorf("can't index %T", current)
		}
	}
	return current, nil
}
func (c CollFuncs) JSONPath(expr string, in interface{}) (interface{}, error) {
	expr=strings.TrimSpace(expr)
	if strings.HasPrefix(expr, "$.") { expr=strings.TrimPrefix(expr, "$.") } else if expr=="$" { return in, nil }
	parts:=strings.Split(expr, ".")
	current:=in
	for _, p:=range parts {
		if current==nil { return nil, nil }
		re:=regexp.MustCompile(`^([^\[]+)\[(\d+)\]$`)
		if m:=re.FindStringSubmatch(p); m!=nil {
			key:=m[1]; idx:=toInt(m[2])
			if mp, ok:=current.(map[string]interface{}); ok {
				if v, ok:=mp[key]; ok { current=v } else { return nil, nil }
			}
			if sl, ok:=current.([]interface{}); ok {
				if idx>=0&&idx<len(sl) { current=sl[idx] } else { return nil, nil }
			}
		} else {
			if mp, ok:=current.(map[string]interface{}); ok {
				if v, ok:=mp[p]; ok { current=v } else { return nil, nil }
			} else { return nil, nil }
		}
	}
	return current, nil
}
func (c CollFuncs) JQ(expr string, in interface{}) (interface{}, error) {
	expr=strings.TrimSpace(expr)
	if expr=="." { return in, nil }
	if strings.HasPrefix(expr, ".") {
		expr=strings.TrimPrefix(expr, ".")
		parts:=strings.Split(expr, ".")
		current:=in
		for _, p:=range parts {
			if m, ok:=current.(map[string]interface{}); ok {
				if v, ok:=m[p]; ok { current=v } else { return nil, nil }
			}
		}
		return current, nil
	}
	return in, nil
}

type DataFuncs struct{ dsMap map[string]string; readDS func(string)(interface{}, error); dsCache map[string]interface{}; dsErr map[string]error }
func (d *DataFuncs) getDS(alias string) (interface{}, error) {
	if data, ok := d.dsCache[alias]; ok { return data, d.dsErr[alias] }
	urlStr, ok := d.dsMap[alias]
	if !ok {
		if strings.Contains(alias, "://") {
			data, err := d.readDS(alias)
			d.dsCache[alias]=data; d.dsErr[alias]=err
			return data, err
		}
		return nil, fmt.Errorf("undefined datasource '%s'", alias)
	}
	data, err := d.readDS(urlStr)
	d.dsCache[alias]=data; d.dsErr[alias]=err
	return data, err
}
func (d *DataFuncs) JSON(in string) (interface{}, error) {
