}
func (s StringFuncs) ShellQuote(input string) string { return "'" + strings.ReplaceAll(input, "'", "'\"'\"'") + "'" }
func (s StringFuncs) Abbrev(args ...interface{}) string {
	var offset int=0; var width int; var input string
	if len(args)==2 { width=toInt(args[0]); input=fmt.Sprintf("%v", args[1]) } else if len(args)==3 { offset=toInt(args[0]); width=toInt(args[1]); input=fmt.Sprintf("%v", args[2]) }
	if len(input)<=width { return input }
	if offset<4 { return input[:width-3]+"..." }
	end:=offset+width-6
	if end>len(input) { end=len(input) }
	return "..." + input[offset:end] + "..."
}
func (s StringFuncs) Trunc(args ...interface{}) string {
	var offset, width int; var input string
	if len(args)==2 { width=toInt(args[0]); input=fmt.Sprintf("%v", args[1]) } else if len(args)==3 { offset=toInt(args[0]); width=toInt(args[1]); input=fmt.Sprintf("%v", args[2]) }
	if offset>=len(input) { return "" }
	end:=offset+width
	if end>len(input) { end=len(input) }
	return input[offset:end]
}
func (s StringFuncs) Indent(spaces int, input string) string {
	pad:=strings.Repeat(" ", spaces)
	lines:=strings.Split(input, "\n")
	for i,l:=range lines { lines[i]=pad+l }
	return strings.Join(lines, "\n")
}
func (s StringFuncs) WordWrap(width int, input string) string {
	words:=strings.Fields(input)
	var outLines []string
	var line string
	for _, w:=range words {
		if len(line)+len(w)+1>width {
			outLines=append(outLines, line)
			line=w
		} else {
			if line=="" { line=w } else { line+=" "+w }
		}
	}
	if line!="" { outLines=append(outLines, line) }
	return strings.Join(outLines, "\n")
}
func (s StringFuncs) RuneCount(input string) int { return len([]rune(input)) }
func (s StringFuncs) SkipLines(n int, input string) string {
	lines:=strings.Split(input, "\n")
	if n>=len(lines) { return "" }
	return strings.Join(lines[n:], "\n")
}
func (s StringFuncs) CamelCase(input string) string {
	parts:=regexp.MustCompile(`[_\-\s]+`).Split(input,-1)
	for i,p:=range parts { if len(p)>0 { parts[i]=strings.Title(strings.ToLower(p)) } }
	res:=strings.Join(parts,"")
	if len(res)>0 { res=strings.ToLower(res[:1])+res[1:] }
	return res
}
func (s StringFuncs) SnakeCase(input string) string {
	re:=regexp.MustCompile(`([a-z0-9])([A-Z])`)
	input=re.ReplaceAllString(input, "${1}_${2}")
	re2:=regexp.MustCompile(`[\s-]+`)
	input=re2.ReplaceAllString(input, "_")
	return strings.ToLower(input)
}
func (s StringFuncs) KebabCase(input string) string {
	re:=regexp.MustCompile(`([a-z0-9])([A-Z])`)
	input=re.ReplaceAllString(input, "${1}-${2}")
	re2:=regexp.MustCompile(`[_\s]+`)
	input=re2.ReplaceAllString(input, "-")
	return strings.ToLower(input)
}

type MathFuncs struct{}
func (m MathFuncs) Add(args ...interface{}) interface{} {
	hasFloat:=false
	for _, a:=range args { if isFloat(a){hasFloat=true;break} }
	if hasFloat { var sum float64; for _,a:=range args{ sum+=toFloat64(a)}; return sum }
	var sum int64; for _,a:=range args{ sum+=toInt64(a)}; return sum
}
func (m MathFuncs) Mul(args ...interface{}) interface{} {
	hasFloat:=false
	for _, a:=range args { if isFloat(a){hasFloat=true;break} }
	if hasFloat { prod:=1.0; for _,a:=range args{ prod*=toFloat64(a)}; return prod }
	var prod int64=1; for _,a:=range args{ prod*=toInt64(a)}; return prod
}
func (m MathFuncs) Sub(a,b interface{}) interface{} {
	if isFloat(a)||isFloat(b){ return toFloat64(a)-toFloat64(b)}
	return toInt64(a)-toInt64(b)
}
func (m MathFuncs) Div(a,b interface{}) float64 { return toFloat64(a)/toFloat64(b) }
func (m MathFuncs) Pow(a,b interface{}) float64 { return math.Pow(toFloat64(a), toFloat64(b)) }
func (m MathFuncs) Rem(a,b interface{}) interface{} {
	ai:=toInt64(a); bi:=toInt64(b); if bi==0 {return 0}; return ai%bi
}
func (m MathFuncs) Abs(v interface{}) interface{} {
	if isFloat(v){ return math.Abs(toFloat64(v))}
	i:=toInt64(v); if i<0 {return -i}; return i
}
func (m MathFuncs) Ceil(v interface{}) float64 { return math.Ceil(toFloat64(v)) }
func (m MathFuncs) Floor(v interface{}) float64 { return math.Floor(toFloat64(v)) }
func (m MathFuncs) Round(v interface{}) float64 { return math.Round(toFloat64(v)) }
func (m MathFuncs) Max(args ...interface{}) interface{} {
	if len(args)==0 {return nil}
	hasFloat:=false; for _,a:=range args{ if isFloat(a){hasFloat=true}}
	if hasFloat {
		max:=toFloat64(args[0]); for _,a:=range args[1:]{ f:=toFloat64(a); if f>max{max=f}}; return max
	}
	max:=toInt64(args[0]); for _,a:=range args[1:]{ i:=toInt64(a); if i>max{max=i}}; return max
}
func (m MathFuncs) Min(args ...interface{}) interface{} {
	if len(args)==0 {return nil}
	hasFloat:=false; for _,a:=range args{ if isFloat(a){hasFloat=true}}
	if hasFloat {
		min:=toFloat64(args[0]); for _,a:=range args[1:]{ f:=toFloat64(a); if f<min{min=f}}; return min
	}
	min:=toInt64(args[0]); for _,a:=range args[1:]{ i:=toInt64(a); if i<min{min=i}}; return min
}
func (m MathFuncs) IsFloat(v interface{}) bool {
	switch x:=v.(type) {
	case float32,float64: return true
	case string:
		_, err:=strconv.ParseFloat(x,64)
		if err!=nil {return false}
		lower:=strings.ToLower(x)
		if lower=="nan"||lower=="inf"||lower=="+inf"||lower=="-inf" {return true}
		return strings.Contains(x,".") || strings.Contains(strings.ToLower(x),"e")
	default: return false
	}
}
func (m MathFuncs) IsInt(v interface{}) bool {
	switch x:=v.(type) {
	case int,int8,int16,int32,int64,uint,uint8,uint16,uint32,uint64: return true
	case string:
		_, err:=strconv.ParseInt(x,0,64)
		return err==nil
	default: return false
	}
}
func (m MathFuncs) IsNum(v interface{}) bool {
	switch x:=v.(type) {
	case int,int8,int16,int32,int64,uint,uint8,uint16,uint32,uint64,float32,float64: return true
	case string:
		if _, err:=strconv.ParseInt(x,0,64); err==nil {return true}
		if _, err:=strconv.ParseFloat(x,64); err==nil {return true}
		lower:=strings.ToLower(x)
		if lower=="nan"||lower=="inf"||lower=="+inf"||lower=="-inf" {return true}
		return false
	default: return false
	}
}
func (m MathFuncs) Seq(args ...interface{}) []int64 {
	var start,end,step int64=0,0,1
	if len(args)>=3 { start=toInt64(args[0]); end=toInt64(args[1]); step=toInt64(args[2]) } else if len(args)==2 { start=toInt64(args[0]); end=toInt64(args[1]); step=1 }
	if step==0 {return []int64{}}
	if end<start && step>0 { step=-step }
	if end>start && step<0 { step=-step }
	end-=(end-start)%step
	seq:=[]int64{start}
	last:=start
	for last!=end {
		last=seq[len(seq)-1]+step
		seq=append(seq, last)
	}
	return seq
}

