type SemverFuncs struct{}
func (s SemverFuncs) Semver(v string) (SemverVersion, error) {
	orig:=v
	if strings.HasPrefix(v,"v") { v=v[1:] }
	parts:=strings.Split(v,".")
	major, minor, patch:=0,0,0
	if len(parts)>0 { major=toInt(parts[0]) }
	if len(parts)>1 { minor=toInt(parts[1]) }
	if len(parts)>2 {
		patchStr:=parts[2]
		if idx:=strings.Index(patchStr,"-"); idx!=-1 { patchStr=patchStr[:idx] }
		patch=toInt(patchStr)
	}
	sv:=SemverVersion{Major:major,Minor:minor,Patch:patch,Version:fmt.Sprintf("%d.%d.%d", major,minor,patch),Orig:orig}
	return sv, nil
}
func (s SemverFuncs) CheckConstraint(constraint, version string) bool {
	constraint=strings.TrimSpace(constraint); version=strings.TrimSpace(version)
	if strings.HasPrefix(version,"v") { version=version[1:] }
	constraints:=strings.Split(constraint, ",")
	for _, c:=range constraints {
		c=strings.TrimSpace(c)
		if strings.HasPrefix(c, ">") {
			vStr:=strings.TrimSpace(strings.TrimPrefix(c, ">"))
			if strings.HasPrefix(vStr, "=") {
				vStr=strings.TrimSpace(strings.TrimPrefix(vStr, "="))
				if compareSemver(version, vStr)<0 { return false }
			} else {
				if compareSemver(version, vStr)<=0 { return false }
			}
		} else if strings.HasPrefix(c, "<") {
			vStr:=strings.TrimSpace(strings.TrimPrefix(c, "<"))
			if strings.HasPrefix(vStr, "=") {
				vStr=strings.TrimSpace(strings.TrimPrefix(vStr, "="))
				if compareSemver(version, vStr)>0 { return false }
			} else {
				if compareSemver(version, vStr)>=0 { return false }
			}
		} else if strings.HasPrefix(c, "=") {
			vStr:=strings.TrimSpace(strings.TrimPrefix(c, "="))
			if compareSemver(version, vStr)!=0 { return false }
		}
	}
	return true
}

