	m:=parseSimpleTOML(in)
	return m, nil
}
func (d *DataFuncs) CSV(args ...string) ([][]string, error) {
	var delim string=","; var input string
	if len(args)==1 { input=args[0] } else if len(args)==2 { delim=args[0]; input=args[1] } else { return nil, fmt.Errorf("invalid args") }
	r:=csv.NewReader(strings.NewReader(input))
	if delim!="" { r.Comma=rune(delim[0]) }
	records, err:=r.ReadAll()
	return records, err
}
func (d *DataFuncs) CSVByRow(args ...string) ([]map[string]string, error) {
	var delim string=","; var input string
	if len(args)==1 { input=args[0] } else if len(args)==2 { delim=args[0]; input=args[1] } else if len(args)==3 { delim=args[0]; input=args[2] }
	r:=csv.NewReader(strings.NewReader(input))
	if delim!="" { r.Comma=rune(delim[0]) }
	records, err:=r.ReadAll()
	if err!=nil { return nil, err }
	if len(records)<1 { return nil, nil }
	header:=records[0]
	var result []map[string]string
	for _, row:=range records[1:] {
		m:=make(map[string]string)
		for i,h:=range header { if i<len(row) { m[h]=row[i] } }
		result=append(result, m)
	}
	return result, nil
}
func (d *DataFuncs) CSVByColumn(args ...string) (map[string][]string, error) {
	var delim string=","; var input string
	if len(args)==1 { input=args[0] } else if len(args)==2 { delim=args[0]; input=args[1] } else if len(args)==3 { delim=args[0]; input=args[2] }
	r:=csv.NewReader(strings.NewReader(input))
	if delim!="" { r.Comma=rune(delim[0]) }
	records, err:=r.ReadAll()
	if err!=nil { return nil, err }
	if len(records)<1 { return nil, nil }
	header:=records[0]
	result:=make(map[string][]string)
	for _, h:=range header { result[h]=[]string{} }
	for _, row:=range records[1:] {
		for i,h:=range header { if i<len(row) { result[h]=append(result[h], row[i]) } }
	}
	return result, nil
}
func (d *DataFuncs) ToJSON(v interface{}) (string, error) { b, err:=json.Marshal(v); return string(b), err }
func (d *DataFuncs) ToJSONPretty(args ...interface{}) (string, error) {
	var indent string; var obj interface{}
	if len(args)==2 {
		if s, ok:=args[0].(string); ok { indent=s; obj=args[1] } else { indent=fmt.Sprintf("%v", args[1]); obj=args[0] }
	} else { return "", fmt.Errorf("invalid args") }
	b, err:=json.MarshalIndent(obj, "", indent)
	return string(b), err
}
func (d *DataFuncs) ToYAML(v interface{}) (string, error) {
	// Simple yaml from map
	if m, ok:=v.(map[string]interface{}); ok {
		var sb strings.Builder
		for k,val:=range m {
			sb.WriteString(fmt.Sprintf("%s: %v\n", k, val))
		}
		return sb.String(), nil
	}
	b, err:=json.Marshal(v)
	return string(b), err
}
func (d *DataFuncs) ToTOML(v interface{}) (string, error) {
	if m, ok:=v.(map[string]interface{}); ok {
		var sb strings.Builder
		for k,val:=range m {
			sb.WriteString(fmt.Sprintf("%s = %q\n", k, fmt.Sprintf("%v", val)))
		}
		return sb.String(), nil
	}
	return "", nil
}
func (d *DataFuncs) ToCSV(args ...interface{}) (string, error) {
	var delim string=","; var input [][]string
	if len(args)==1 {
		if arr, ok:=args[0].([][]string); ok { input=arr }
	} else if len(args)==2 {
		if d, ok:=args[0].(string); ok { delim=d; if arr, ok:=args[1].([][]string); ok { input=arr } }
	}
	var buf bytes.Buffer
	w:=csv.NewWriter(&buf)
	if delim!="" { w.Comma=rune(delim[0]) }
	for _, rec:=range input { w.Write(rec) }
	w.Flush()
	return buf.String(), w.Error()
}

func buildFuncMap(dsMap map[string]string, contextMap map[string]interface{}, readDS func(string)(interface{}, error), pf ParsedFlags) template.FuncMap {
	fm:=template.FuncMap{}
	dsCache:=make(map[string]interface{})
	dsErrCache:=make(map[string]error)
	getDS:=func(alias string) (interface{}, error) {
		if data, ok:=dsCache[alias]; ok { return data, dsErrCache[alias] }
		urlStr, ok:=dsMap[alias]
		if !ok {
			if strings.Contains(alias, "://") {
				data, err:=readDS(alias)
				dsCache[alias]=data; dsErrCache[alias]=err
				return data, err
			}
			return nil, fmt.Errorf("undefined datasource '%s'", alias)
		}
		data, err:=readDS(urlStr)
		dsCache[alias]=data; dsErrCache[alias]=err
		return data, err
	}

	fm["datasource"]=func(args ...string) (interface{}, error) {
		if len(args)<1 { return nil, fmt.Errorf("datasource requires alias") }
		alias:=args[0]; subpath:=""
		if len(args)>1 { subpath=args[1] }
		data, err:=getDS(alias)
		if err!=nil { return nil, fmt.Errorf("couldn't read datasource '%s' (%s): %w", alias, dsMap[alias], err) }
		if subpath!="" {
			if m, ok:=data.(map[string]interface{}); ok {
				if v, ok:=m[subpath]; ok { return v, nil }
			}
			origURL:=dsMap[alias]
			basePath:=origURL
			if strings.HasPrefix(basePath, "file://") { basePath=strings.TrimPrefix(basePath, "file://") }
			if info, err:=os.Stat(basePath); err==nil && !info.IsDir() { basePath=filepath.Dir(basePath) }
			newPath:=filepath.Join(basePath, subpath)
			if b, err:=os.ReadFile(newPath); err==nil {
				mime:=mimeFromExt(filepath.Ext(newPath))
				return parseContent(b, mime, newPath)
			}
			return nil, fmt.Errorf("couldn't read datasource '%s' (file://%s)", alias, filepath.Join("/tmp", subpath))
		}
		return data, nil
	}
	fm["ds"]=fm["datasource"]
	fm["include"]=func(args ...string) (string, error) {
		if len(args)<1 { return "", fmt.Errorf("include requires alias") }
		alias:=args[0]; subpath:=""
		if len(args)>1 { subpath=args[1] }
		data, err:=getDS(alias)
		if err!=nil { return "", fmt.Errorf("couldn't read datasource '%s': %w", alias, err) }
		if subpath!="" {
			origURL:=dsMap[alias]
			basePath:=origURL
			if strings.HasPrefix(basePath, "file://") { basePath=strings.TrimPrefix(basePath, "file://") }
			if info, err:=os.Stat(basePath); err==nil && !info.IsDir() { basePath=filepath.Dir(basePath) }
			newPath:=filepath.Join(basePath, subpath)
			if b, err:=os.ReadFile(newPath); err==nil { return string(b), nil }
		}
		if s, ok:=data.(string); ok { return s, nil }
		b,_:=json.Marshal(data)
		return string(b), nil
	}
	fm["datasourceExists"]=func(alias string) bool { _, ok:=dsMap[alias]; return ok }
	fm["datasourceReachable"]=func(alias string) bool { _, err:=getDS(alias); return err==nil }
	fm["listDatasources"]=func() []string {
		var keys []string; for k:=range dsMap { keys=append(keys,k) }; sort.Strings(keys); return keys
	}
	fm["defineDatasource"]=func(alias, urlStr string) string {
		if _, ok:=dsMap[alias]; !ok { dsMap[alias]=urlStr }
		return ""
	}

	fm["strings"]=func() StringFuncs { return StringFuncs{} }
	fm["math"]=func() MathFuncs { return MathFuncs{} }
	fm["base64"]=func() Base64Funcs { return Base64Funcs{} }
	fm["crypto"]=func() CryptoFuncs { return CryptoFuncs{Experimental: pf.Experimental} }
	fm["uuid"]=func() UUIDFuncs { return UUIDFuncs{} }
	fm["random"]=func() RandomFuncs { return RandomFuncs{} }
	fm["regexp"]=func() RegexpFuncs { return RegexpFuncs{} }
	fm["time"]=func() TimeFuncs { return TimeFuncs{} }
	fm["net"]=func() NetFuncs { return NetFuncs{} }
	fm["env"]=func() EnvFuncs { return EnvFuncs{} }
	fm["file"]=func() FileFuncs { return FileFuncs{} }
	fm["filepath"]=func() FilePathFuncs { return FilePathFuncs{} }
	fm["path"]=func() PathFuncs { return PathFuncs{} }
	fm["conv"]=func() ConvFuncs { return ConvFuncs{} }
	fm["coll"]=func() CollFuncs { return CollFuncs{} }
	fm["data"]=func() *DataFuncs { return &DataFuncs{dsMap: dsMap, readDS: readDS, dsCache: dsCache, dsErr: dsErrCache} }
	fm["semver"]=func() SemverFuncs { return SemverFuncs{} }
	fm["sockaddr"]=func() SockaddrFuncs { return SockaddrFuncs{} }
	fm["test"]=func() TestFuncs { return TestFuncs{} }
	fm["tmpl"]=func() TmplFuncs { return TmplFuncs{} }

	mf:=MathFuncs{}
	fm["add"]=mf.Add
	fm["mul"]=mf.Mul
	fm["div"]=mf.Div
	fm["sub"]=func(a,b interface{}) interface{} { return mf.Sub(a,b) }

	cf:=CollFuncs{}
	fm["dict"]=cf.Dict
	fm["has"]=cf.Has
	fm["keys"]=cf.Keys
	fm["values"]=cf.Values
	fm["append"]=cf.Append
	fm["prepend"]=cf.Prepend
	fm["uniq"]=cf.Uniq
	fm["flatten"]=cf.Flatten

	convf:=ConvFuncs{}
	fm["default"]=convf.Default
	fm["join"]=convf.Join
	fm["toJSON"]=func(v interface{}) string { b,_:=json.Marshal(v); return string(b) }
	fm["toYAML"]=func(v interface{}) string {
		if m, ok:=v.(map[string]interface{}); ok {
			var sb strings.Builder
			for k,val:=range m { sb.WriteString(fmt.Sprintf("%s: %v\n", k, val)) }
			return sb.String()
		}
		b,_:=json.Marshal(v)
		return string(b)
	}

	envf:=EnvFuncs{}
	fm["getenv"]=envf.Getenv

	testf:=TestFuncs{}
	fm["assert"]=testf.Assert
	fm["fail"]=testf.Fail
	fm["ternary"]=testf.Ternary
	fm["isKind"]=testf.IsKind
	fm["kind"]=testf.Kind
	fm["required"]=testf.Required

	for _, p:=range pf.Plugins {
		alias, pathStr := parseDatasourceArg(p)
		aliasCopy:=alias; pathCopy:=pathStr
		fm[aliasCopy]=func(args ...interface{}) (string, error) {
			var cmdArgs []string
			for _, a:=range args { cmdArgs=append(cmdArgs, fmt.Sprintf("%v", a)) }
			return runPlugin(pathCopy, cmdArgs, "")
		}
	}

	return fm
}

func isSlice(v interface{}) bool {
	switch v.(type) {
	case []interface{}, []string, [][]string, []int, []int64: return true
	default: return false
	}
}

func toSlice(v interface{}) []interface{} {
	switch x:=v.(type) {
	case []interface{}: return x
	case []string:
		var res []interface{}; for _, s:=range x { res=append(res, s) }; return res
	case [][]string:
		var res []interface{}; for _, r:=range x { res=append(res, r) }; return res
	default: return []interface{}{v}
	}
}

func toInt(v interface{}) int { return int(toInt64(v)) }

func toInt64(v interface{}) int64 {
	switch x:=v.(type) {
	case int: return int64(x)
	case int64: return x
	case int32: return int64(x)
	case uint: return int64(x)
	case uint64: return int64(x)
	case float64: return int64(x)
	case float32: return int64(x)
	case string:
		s:=strings.TrimSpace(x)
		if s=="" { return 0 }
		lower:=strings.ToLower(s)
		if lower=="nan"||lower=="inf"||lower=="+inf"||lower=="-inf" { return 0 }
		if i, err:=strconv.ParseInt(s,0,64); err==nil { return i }
		if f, err:=strconv.ParseFloat(s,64); err==nil { return int64(f) }
		return 0
	default: return 0
	}
}

func toFloat64(v interface{}) float64 {
	switch x:=v.(type) {
	case int: return float64(x)
	case int64: return float64(x)
	case float64: return x
	case float32: return float64(x)
	case string:
		if f, err:=strconv.ParseFloat(x,64); err==nil { return f }
		if i, err:=strconv.ParseInt(x,0,64); err==nil { return float64(i) }
		return 0
	default: return 0
	}
}

func toBool(v interface{}) bool {
	switch x:=v.(type) {
	case bool: return x
	case string:
		lower:=strings.ToLower(strings.TrimSpace(x))
		if lower=="1" || lower=="t" || lower=="true" || lower=="yes" { return true }
		return false
	case int: return x==1
	case int64: return x==1
	case int32: return x==1
	case float64: return x==1
	case float32: return x==1
	case nil: return false
	default: return false
	}
}

func isFloat(v interface{}) bool {
	switch x:=v.(type) {
	case float32,float64: return true
	case string:
		_, err:=strconv.ParseFloat(x,64)
		return err==nil && (strings.Contains(x, ".") || strings.Contains(strings.ToLower(x), "e"))
	default: return false
	}
}

func isEmpty(v interface{}) bool {
	if v==nil { return true }
	switch x:=v.(type) {
	case string: return x==""
	case bool: return !x
	case int: return x==0
	case int64: return x==0
	case float64: return x==0
	case []interface{}: return len(x)==0
	case []string: return len(x)==0
	case map[string]interface{}: return len(x)==0
	case map[string]string: return len(x)==0
	default: return false
	}
}

func getKind(v interface{}) string {
	if v==nil { return "invalid" }
	switch v.(type) {
	case string: return "string"
	case bool: return "bool"
	case int,int8,int16,int32,int64: return "int"
	case uint,uint8,uint16,uint32,uint64: return "uint"
	case float32,float64: return "float64"
	case []interface{}, []string, [][]string: return "slice"
	case map[string]interface{}, map[string]string: return "map"
	default: return fmt.Sprintf("%T", v)
	}
}

func compareSemver(a,b string) int {
	partsA:=strings.Split(a,".")
	partsB:=strings.Split(b,".")
	maxLen:=len(partsA)
	if len(partsB)>maxLen { maxLen=len(partsB) }
	for i:=0; i<maxLen; i++ {
		var av,bv int
		if i<len(partsA) { av=toInt(partsA[i]) }
		if i<len(partsB) { bv=toInt(partsB[i]) }
		if av<bv { return -1 }
		if av>bv { return 1 }
	}
	return 0
}

func processInputDir(pf ParsedFlags, funcMap template.FuncMap, contextMap map[string]interface{}, rootOverride interface{}, dsMap map[string]string, readDS func(string)(interface{}, error)) error {
	inputDir:=pf.InputDir
	outputDir:=pf.OutputDir
	outputMapStr:=pf.OutputMap

	var files []string
	err:=filepath.Walk(inputDir, func(p string, info os.FileInfo, err error) error {
		if err!=nil { return err }
		if info.IsDir() { return nil }
		files=append(files, p)
		return nil
	})
	if err!=nil { return err }

	var ignorePatterns []string
	if b, err := os.ReadFile(filepath.Join(inputDir, ".gomplateignore")); err==nil {
		lines:=strings.Split(string(b), "\n")
		for _, l:=range lines {
			l=strings.TrimSpace(l)
			if l!="" && !strings.HasPrefix(l, "#") { ignorePatterns=append(ignorePatterns, l) }
		}
	}

	var filtered []string
	for _, f:=range files {
		rel, _ := filepath.Rel(inputDir, f)
		if len(pf.Includes)>0 {
			matched:=false
			for _, pat:=range pf.Includes {
				if ok,_:=filepath.Match(pat, filepath.Base(f)); ok { matched=true; break }
				if ok,_:=filepath.Match(pat, rel); ok { matched=true; break }
			}
			if !matched { continue }
		}
		excluded:=false
		for _, pat:=range pf.Excludes {
			if strings.HasPrefix(pat, "!") {
				negPat:=strings.TrimPrefix(pat, "!")
				if ok,_:=filepath.Match(negPat, filepath.Base(f)); ok { excluded=false; continue }
				if ok,_:=filepath.Match(negPat, rel); ok { excluded=false; continue }
			} else {
				if ok,_:=filepath.Match(pat, filepath.Base(f)); ok { excluded=true }
				if ok,_:=filepath.Match(pat, rel); ok { excluded=true }
			}
		}
		for _, pat:=range ignorePatterns {
			if ok,_:=filepath.Match(pat, filepath.Base(f)); ok { excluded=true }
			if ok,_:=filepath.Match(pat, rel); ok { excluded=true }
		}
		if excluded { continue }
		filtered=append(filtered, f)
	}

	for _, f:=range filtered {
		rel, _ := filepath.Rel(inputDir, f)
		isExcludeProcessing:=false
		for _, pat:=range pf.ExcludeProcessing {
			if ok,_:=filepath.Match(pat, filepath.Base(f)); ok { isExcludeProcessing=true; break }
			if ok,_:=filepath.Match(pat, rel); ok { isExcludeProcessing=true; break }
		}
		var outPath string
		if outputMapStr!="" {
			dotMap:=make(map[string]interface{})
			for k,v:=range contextMap { dotMap[k]=v }
			dotMap["in"]=rel
			if rootOverride!=nil {
				if m, ok:=rootOverride.(map[string]interface{}); ok {
					dotMap["ctx"]=m
					for k,v:=range m {
						if k!="in" && k!="ctx" {
							if _, exists:=dotMap[k]; !exists { dotMap[k]=v }
						}
					}
				} else { dotMap["ctx"]=rootOverride }
			} else { dotMap["Env"]=getEnvMap() }
			tmpl:=template.New("output-map")
			tmpl.Option("missingkey=zero")
			tmpl.Delims(pf.LeftDelim, pf.RightDelim)
			tmpl.Funcs(funcMap)
			for _, tArg:=range pf.Templates {
				alias, pathStr := parseTemplateArg(tArg)
				if b, err := os.ReadFile(pathStr); err==nil { tmpl.New(alias).Parse(string(b)) }
			}
			parsed, err := tmpl.Parse(outputMapStr)
			if err!=nil { return fmt.Errorf("failed to parse output-map: %v", err) }
			var buf bytes.Buffer
			err=parsed.Execute(&buf, dotMap)
			if err!=nil { return fmt.Errorf("failed to render output-map: %v", err) }
			outPath=strings.TrimSpace(buf.String())
		} else {
			outPath=filepath.Join(outputDir, rel)
		}

		if isExcludeProcessing {
			os.MkdirAll(filepath.Dir(outPath), 0755)
			b, err := os.ReadFile(f)
			if err!=nil { return err }
			err=os.WriteFile(outPath, b, 0644)
			if err!=nil { return err }
			continue
		}
		b, err := os.ReadFile(f)
		if err!=nil { return err }
		var dot interface{}
		if rootOverride!=nil { dot=rootOverride } else {
			m:=make(map[string]interface{})
			for k,v:=range contextMap { m[k]=v }
			m["Env"]=getEnvMap()
			dot=m
		}
		tmpl:=template.New(f)
		tmpl.Option("missingkey=" + pf.MissingKey)
		tmpl.Delims(pf.LeftDelim, pf.RightDelim)
		tmpl.Funcs(funcMap)
		for _, tArg:=range pf.Templates {
			alias, pathStr := parseTemplateArg(tArg)
			if b, err := os.ReadFile(pathStr); err==nil { tmpl.New(alias).Parse(string(b)) }
		}
		parsed, err := tmpl.Parse(string(b))
		if err!=nil { return fmt.Errorf("renderTemplate: failed to render template %s: template: %s: %v", f, f, err) }
		var buf bytes.Buffer
		err=parsed.Execute(&buf, dot)
		if err!=nil { return fmt.Errorf("renderTemplate: failed to render template %s: template: %s: %v", f, f, err) }
		output:=buf.String()
		if strings.TrimSpace(output)=="" { continue }
		os.MkdirAll(filepath.Dir(outPath), 0755)
		err=os.WriteFile(outPath, []byte(output), 0644)
		if err!=nil { return err }
		if pf.Chmod!="" {
			mode,err:=strconv.ParseUint(pf.Chmod,8,32)
			if err==nil { os.Chmod(outPath, os.FileMode(mode)) }
		} else {
			if info,err:=os.Stat(f); err==nil { os.Chmod(outPath, info.Mode()) }
		}
	}
	return nil
}

func runPlugin(path string, args []string, stdin string) (string, error) {
	cmd:=exec.Command(path, args...)
	if stdin!="" { cmd.Stdin=strings.NewReader(stdin) }
	var out bytes.Buffer
	var errBuf bytes.Buffer
	cmd.Stdout=&out
	cmd.Stderr=&errBuf
	err:=cmd.Run()
	if errBuf.Len()>0 { fmt.Fprint(os.Stderr, errBuf.String()) }
	if err!=nil { return "", err }
	return out.String(), nil
}

func runPostExec(cmdArgs []string, input string, usePipe bool) error {
	if len(cmdArgs)==0 { return nil }
	cmd:=exec.Command(cmdArgs[0], cmdArgs[1:]...)
	if usePipe {
		cmd.Stdin=strings.NewReader(input)
		cmd.Stdout=os.Stdout
		cmd.Stderr=os.Stderr
		return cmd.Run()
	}
	cmd.Stdout=os.Stdout
	cmd.Stderr=os.Stderr
	cmd.Stdin=os.Stdin
	return cmd.Run()
}
